} from 'lucide-react';

interface CategoryListProps {
  categories: Category[];
  activeCategoryId: number;
  onSelectCategory: (id: number) => void;
}

// Map category IDs to specific icons
const getCategoryIcon = (id: number): LucideIcon => {
  switch (id) {
    case 0: return LayoutGrid;    // Todos
    case -1: return Heart;        // Favoritos
    case 8: return Flame;         // BBB
    case 6: return Tv;            // TV Aberta
    case 1: return Trophy;        // Esportes
    case 4: return Clapperboard;  // Filmes e Séries
    case 2: return Baby;          // Infantil
    case 5: return Newspaper;     // Noticias
    case 3: return Globe;         // Documentarios
    case 7: return Shuffle;       // Variedades
    default: return Tv;
  }
};

export const CategoryList: React.FC<CategoryListProps> = ({ 
  categories, 
  activeCategoryId, 
  onSelectCategory 
}) => {
  return (
    <div className="w-full bg-dark border-b border-gray-800 sticky top-[65px] z-40 shadow-sm">
      <div className="container mx-auto px-4 py-3">
        <div className="flex gap-3 overflow-x-auto no-scrollbar pb-1">
          {categories.map((category) => {
            const Icon = getCategoryIcon(category.id);
            const isActive = activeCategoryId === category.id;

            return (
              <button
                key={category.id}
                onClick={() => onSelectCategory(category.id)}
                className={`
                  whitespace-nowrap px-4 py-2 rounded-xl text-sm font-semibold transition-all duration-300
                  flex items-center gap-2 flex-shrink-0 border
                  ${isActive 
                    ? 'bg-primary text-white border-primary shadow-lg shadow-primary/25 scale-105' 
                    : 'bg-card text-gray-400 border-gray-700 hover:bg-gray-700 hover:text-white hover:border-gray-500'}
                `}
              >
                <Icon className={`w-4 h-4 ${isActive ? 'text-white' : 'text-gray-500 group-hover:text-white'} ${category.id === -1 && !isActive ? 'text-primary' : ''}`} />
                {category.name}
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { Header } from '../components/Header';
import { CategoryList } from '../components/CategoryList';
import { ChannelGrid } from '../components/ChannelGrid';
import { Channel, Category } from '../types';

interface HomeProps {
  channels: Channel[];
  categories: Category[];
  favorites: string[];
  toggleFavorite: (id: string) => void;
}

export const Home: React.FC<HomeProps> = ({ channels, categories, favorites, toggleFavorite }) => {
  const navigate = useNavigate();
  const [activeCategoryId, setActiveCategoryId] = useState<number>(0);
  const [searchQuery, setSearchQuery] = useState<string>("");

  // Filter Logic
  const filteredChannels = useMemo(() => {
    return channels.filter((channel) => {
      // Search Logic
      const matchesSearch = channel.name.toLowerCase().includes(searchQuery.toLowerCase());
      if (!matchesSearch) return false;

      // Category Logic
      if (activeCategoryId === 0) return true; // Todos
      if (activeCategoryId === -1) {
        // Favoritos
        return favorites.includes(channel.id);
      }
      return channel.categories.includes(activeCategoryId);
    });
  }, [channels, activeCategoryId, searchQuery, favorites]);

  const handleChannelSelect = (channel: Channel) => {
    navigate(`/watch/${channel.id}`);
  };

  const handleCategorySelect = (id: number) => {
    setActiveCategoryId(id);
  };

  return (
    <div className="flex-1 flex flex-col">
      <Header 
        searchTerm={searchQuery} 
        onSearch={setSearchQuery} 
      />

      <CategoryList 
        categories={categories} 
        activeCategoryId={activeCategoryId} 
        onSelectCategory={handleCategorySelect} 
      />

      <div className="flex-1">
        <div className="container mx-auto px-4 py-4">
           <div className="flex items-center gap-2 mb-2">
              <div className="w-1 h-6 bg-primary rounded-full"></div>
              <h2 className="text-xl font-bold text-white">
                {categories.find(c => c.id === activeCategoryId)?.name || 'Canais'}
                {searchQuery && <span className="text-gray-400 font-normal text-base ml-2">- Buscando por "{searchQuery}"</span>}
              </h2>
           </div>

           <ChannelGrid 
             channels={filteredChannels} 
             onSelectChannel={handleChannelSelect}
             favorites={favorites}
             onToggleFavorite={toggleFavorite}
           />
        </div>
      </div>

      {/* Simple Footer */}
      <footer className="bg-card py-6 border-t border-gray-800 mt-auto">
        <div className="container mx-auto px-4 text-center">
          <p className="text-gray-500 text-sm">
            © 2024 MegaTV. Projeto Demo. <br className="sm:hidden"/>
            Não hospedamos nenhum vídeo.
          </p>
        </div>
      </footer>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Channel } from '../types';
import { Play, Tv, Loader2, Heart } from 'lucide-react';

interface ChannelCardProps {
  channel: Channel;
  isFavorite: boolean;
  onToggleFavorite: (id: string) => void;
  onClick: () => void;
}

const ChannelCard: React.FC<ChannelCardProps> = ({ channel, isFavorite, onToggleFavorite, onClick }) => {
  const [imageError, setImageError] = useState(false);
  const [imageLoaded, setImageLoaded] = useState(false);

  // Helper to extract initials
  const getInitials = (name: string) => {
    return name
      .replace(/[^a-zA-Z0-9 ]/g, '')
      .split(' ')
      .filter(word => word.length > 0)
      .map(word => word[0])
      .slice(0, 2)
      .join('')
      .toUpperCase() || 'TV';
  };

  // Check if image URL is present
  const hasImage = !!channel.image && channel.image.trim() !== '';

  const handleFavoriteClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    onToggleFavorite(channel.id);
  };

  return (
    <div
      onClick={onClick}
      className="group relative bg-card hover:bg-gray-700 rounded-xl overflow-hidden cursor-pointer transition-all duration-300 hover:shadow-xl hover:shadow-primary/10 hover:-translate-y-1 border border-gray-800 hover:border-gray-600 flex flex-col h-full"
    >
      {/* Image Aspect Ratio Container */}
      <div className="aspect-video w-full bg-gray-900 relative p-4 flex items-center justify-center">

        {/* Favorite Button - Absolute Top Right */}
        <button
          onClick={handleFavoriteClick}
          className="absolute top-2 right-2 z-20 p-2 rounded-full bg-black/40 hover:bg-black/60 backdrop-blur-sm transition-all duration-200 group-hover:opacity-100 opacity-100 sm:opacity-0"
          title={isFavorite ? "Remover dos favoritos" : "Adicionar aos favoritos"}
        >
          <Heart 
            className={`w-5 h-5 transition-colors duration-200 ${isFavorite ? 'text-primary fill-primary' : 'text-white hover:text-primary'}`} 
          />
        </button>

        {hasImage && !imageError ? (
          <>
            {!imageLoaded && (
              <div className="absolute inset-0 bg-gray-800 animate-pulse" />
            )}
            <img
              src={channel.image}
              alt={channel.name}
              loading="lazy"
              decoding="async"
              className={`max-h-full max-w-full object-contain transition-all duration-500 group-hover:scale-110 ${
                imageLoaded ? 'opacity-100 blur-0' : 'opacity-0 blur-sm'
              }`}
              onLoad={() => setImageLoaded(true)}
              onError={() => setImageError(true)}
            />
          </>
        ) : (
           <div className="w-full h-full flex flex-col items-center justify-center bg-gray-800/50 rounded-lg select-none">
             <div className="w-12 h-12 rounded-full bg-gray-700 flex items-center justify-center mb-2 shadow-inner">
               <Tv className="w-6 h-6 text-gray-500" />
             </div>
             <span className="text-lg font-bold text-gray-400 tracking-wider">
               {getInitials(channel.name)}
             </span>
           </div>
        )}

        {/* Play Overlay */}
        <div className="absolute inset-0 bg-black/60 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-300 z-10 pointer-events-none">
          <div className="w-12 h-12 bg-primary rounded-full flex items-center justify-center shadow-lg transform scale-0 group-hover:scale-100 transition-transform duration-300 delay-75">
            <Play className="w-6 h-6 text-white fill-current ml-1" />
          </div>
        </div>
      </div>

      {/* Content */}
      <div className="p-3 border-t border-gray-700/50 flex-1 flex flex-col justify-center gap-1">
        <h3 className="font-semibold text-gray-200 text-sm sm:text-base truncate text-center group-hover:text-primary transition-colors">
          {channel.name}
        </h3>

        {/* Info Line: Current Program or Description */}
        {(channel.currentProgram || channel.description) && (
          <div className="flex items-center justify-center gap-1.5 w-full">
              {channel.currentProgram && (
                <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse flex-shrink-0" title="Ao Vivo"></span>
              )}
              <p className="text-xs text-gray-400 truncate max-w-full opacity-80 group-hover:opacity-100 transition-opacity">
                {channel.currentProgram || channel.description}
              </p>
          </div>
        )}
      </div>
    </div>
  );
};

interface ChannelGridProps {
  channels: Channel[];
  favorites: string[];
  onToggleFavorite: (id: string) => void;
  onSelectChannel: (channel: Channel) => void;
}

const ITEMS_PER_PAGE = 24;

export const ChannelGrid: React.FC<ChannelGridProps> = ({ channels, favorites, onToggleFavorite, onSelectChannel }) => {
  const [visibleCount, setVisibleCount] = useState(ITEMS_PER_PAGE);
  const observerRef = useRef<HTMLDivElement | null>(null);

  // Reset visible count when channel list changes (e.g. category switch or search)
  useEffect(() => {
    setVisibleCount(ITEMS_PER_PAGE);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [channels]);

  // Infinite Scroll Observer
  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
          setVisibleCount((prev) => Math.min(prev + ITEMS_PER_PAGE, channels.length));
        }
      },
      {
        root: null, // viewport
        rootMargin: '200px', // load before reaching bottom
        threshold: 0.1,
      }
    );

    if (observerRef.current) {
      observer.observe(observerRef.current);
    }

    return () => {
      if (observerRef.current) {
        observer.unobserve(observerRef.current);
      }
    };
  }, [channels.length]);

  const visibleChannels = channels.slice(0, visibleCount);

  if (channels.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-20 text-gray-500">
        <p className="text-lg">Nenhum canal encontrado.</p>
        <p className="text-sm">Tente mudar a categoria ou sua busca.</p>
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 py-6">
      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-4 sm:gap-6">
        {visibleChannels.map((channel) => (
          <ChannelCard 
            key={channel.id} 
            channel={channel} 
            isFavorite={favorites.includes(channel.id)}
            onToggleFavorite={onToggleFavorite}
            onClick={() => onSelectChannel(channel)} 
          />
        ))}
      </div>

      {/* Sentinel element for infinite scroll */}
      {visibleCount < channels.length && (
        <div 
          ref={observerRef} 
          className="w-full py-8 flex justify-center items-center"
        >
          <Loader2 className="w-8 h-8 text-primary animate-spin" />
        </div>
      )}
    </div>
  );
};

