  }
}

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import { VitePWA } from 'vite-plugin-pwa';

export default defineConfig({
  plugins: [
    react(),
    VitePWA({
      registerType: 'autoUpdate',
      injectRegister: 'auto',
      manifest: {
        name: 'MegaTV - TV Online',
        short_name: 'MegaTV',
        description: 'Assista TV Online Grátis',
        theme_color: '#0f172a',
        background_color: '#0f172a',
        display: 'standalone',
        icons: [
          {
            src: 'https://cdn-icons-png.flaticon.com/512/3135/3135715.png', // Fallback generic TV icon
            sizes: '192x192',
            type: 'image/png'
          },
          {
            src: 'https://cdn-icons-png.flaticon.com/512/3135/3135715.png',
            sizes: '512x512',
            type: 'image/png'
          }
        ]
      },
      workbox: {
        globPatterns: ['**/*.{js,css,html,ico,png,svg}'],
        runtimeCaching: [
          {
            // Strategy: Cache First for Channel Logos
            // Matches: https://embedtv.best/assets/images/*
            urlPattern: ({ url }) => url.hostname === 'embedtv.best' && url.pathname.includes('/assets/images/'),
            handler: 'CacheFirst',
            options: {
              cacheName: 'channel-logos-cache',
              expiration: {
                maxEntries: 100, // Keep most recent 100 logos
                maxAgeSeconds: 60 * 60 * 24 * 30, // Cache for 30 days
              },
              cacheableResponse: {
                statuses: [0, 200],
              },
            },
          },
          {
            // Strategy: Network First for API calls (if we had a real endpoint)
            // or other external resources
            urlPattern: ({ url }) => url.pathname.includes('channels.php'),
            handler: 'NetworkFirst',
            options: {
              cacheName: 'api-cache',
              expiration: {
                maxAgeSeconds: 60 * 60, // 1 hour
              },
              networkTimeoutSeconds: 3,
            },
          }
        ],
      },
    }),
  ],
  build: {
    outDir: 'dist',
  }
});

import { ApiData } from '../types';
import { initialData } from './initialData';

const CACHE_KEY = 'megatv_data_v1';
const CACHE_DURATION = 1000 * 60 * 60; // 1 hour

interface CachedData {
  timestamp: number;
  data: ApiData;
}

export const fetchChannels = async (): Promise<ApiData> => {
  try {
    // 1. Check Local Storage
    const cachedString = localStorage.getItem(CACHE_KEY);

    if (cachedString) {
      try {
        const cached: CachedData = JSON.parse(cachedString);
        const now = Date.now();

        // If cache is valid (less than 1 hour old), return it
        if (now - cached.timestamp < CACHE_DURATION) {
          // console.log("Serving from local cache");
          return Promise.resolve(cached.data);
        }
      } catch (e) {
        console.warn("Cache parse error, refreshing data");
        localStorage.removeItem(CACHE_KEY);
      }
    }

    // 2. Simulate Network Request (Using initialData)
    // In a real app, this would be: const response = await fetch('...');
    const freshData = initialData;

    // 3. Save to Cache
    try {
      const cachePayload: CachedData = {
        timestamp: Date.now(),
        data: freshData
      };
      localStorage.setItem(CACHE_KEY, JSON.stringify(cachePayload));
    } catch (e) {
      console.error("Failed to save to cache (quota exceeded?)", e);
    }

    return Promise.resolve(freshData);
  } catch (error) {
    console.error("Failed to fetch channels:", error);
    return {
      categories: [],
      channels: []
    };
  }
};

