      result = history
        .map(id => channels.find(c => c.id === id))
        .filter((c): c is Channel => !!c);
    } else {
      // Standard Filtering
      result = channels.filter((channel) => {
        // Category Logic
        if (activeCategoryId === 0) return true; // Todos
