import { ApiData, Game } from '../types';
import { initialData } from './initialData';

const CACHE_KEY = 'megacanaistv_data_v1';
const CACHE_DURATION = 1000 * 60 * 60; // 1 hour

interface CachedData {
  timestamp: number;
  data: ApiData;
}

export const fetchChannels = async (): Promise<ApiData> => {
  try {
    // 1. Check Local Storage
    const cachedString = localStorage.getItem(CACHE_KEY);

    if (cachedString) {
      try {
        const cached: CachedData = JSON.parse(cachedString);
        const now = Date.now();

        // If cache is valid (less than 1 hour old), return it
        if (now - cached.timestamp < CACHE_DURATION) {
          // console.log("Serving from local cache");
          return Promise.resolve(cached.data);
        }
      } catch (e) {
        console.warn("Cache parse error, refreshing data");
        localStorage.removeItem(CACHE_KEY);
      }
    }

    // 2. Simulate Network Request (Using initialData)
    const freshData = initialData;

    // 3. Save to Cache
    try {
      const cachePayload: CachedData = {
        timestamp: Date.now(),
        data: freshData
      };
      localStorage.setItem(CACHE_KEY, JSON.stringify(cachePayload));
    } catch (e) {
      console.error("Failed to save to cache (quota exceeded?)", e);
    }

    return Promise.resolve(freshData);
  } catch (error) {
    console.error("Failed to fetch channels:", error);
    return {
      categories: [],
      channels: []
    };
  }
};

export const fetchGames = async (): Promise<Game[]> => {
  try {
    const date = new Date();
    const day = String(date.getDate()).padStart(2, '0');
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const year = date.getFullYear();
    const dateString = `${day}${month}${year}`;

    // Fallback logic for demo purposes: 
    // If today is NOT 18/01/2026 (the example date provided by user which works), 
    // we still try to fetch today's data.
    // Note: The provided API endpoint seems to require `day` parameter.

    const response = await fetch(`https://embedtv.best/jogos.php?day=${dateString}`);

    if (!response.ok) {
       // If today fails (maybe API empty for today), try the known working date from prompt for demo? 
       // Better to just return empty to be realistic, but let's try to be resilient.
       throw new Error('Failed to fetch games');
    }

    const data = await response.json();
    if (Array.isArray(data)) {
      return data;
    }
    return [];
  } catch (error) {
    console.error("Error fetching games:", error);
    return [];
  }
};

import React from 'react';
import { Category } from '../types';
import { 
  LayoutGrid, 
  Flame, 
  Trophy, 
  Baby, 
  Globe, 
  Clapperboard, 
  Newspaper, 
  Tv, 
  Shuffle,
  Heart,
  History,
  Gamepad2,
  LucideIcon 
} from 'lucide-react';

interface CategoryListProps {
  categories: Category[];
  activeCategoryId: number;
  onSelectCategory: (id: number) => void;
}

// Map category IDs to specific icons
const getCategoryIcon = (id: number): LucideIcon => {
  switch (id) {
    case 0: return LayoutGrid;    // Todos
    case -1: return Heart;        // Favoritos
    case -2: return History;      // Recentes
    case -3: return Gamepad2;     // Jogos
    case 8: return Flame;         // BBB
    case 6: return Tv;            // TV Aberta
    case 1: return Trophy;        // Esportes
    case 4: return Clapperboard;  // Filmes e Séries
    case 2: return Baby;          // Infantil
    case 5: return Newspaper;     // Noticias
    case 3: return Globe;         // Documentarios
    case 7: return Shuffle;       // Variedades
    default: return Tv;
  }
};

export const CategoryList: React.FC<CategoryListProps> = ({ 
  categories, 
  activeCategoryId, 
  onSelectCategory 
}) => {
  return (
    <div className="w-full bg-dark border-b border-gray-800 sticky top-[65px] z-40 shadow-sm">
      <div className="container mx-auto px-4 py-3">
        <div className="flex gap-3 overflow-x-auto no-scrollbar pb-1">
          {categories.map((category) => {
            const Icon = getCategoryIcon(category.id);
            const isActive = activeCategoryId === category.id;

            return (
              <button
                key={category.id}
                onClick={() => onSelectCategory(category.id)}
                className={`
                  whitespace-nowrap px-4 py-2 rounded-xl text-sm font-semibold transition-all duration-300
                  flex items-center gap-2 flex-shrink-0 border
                  ${isActive 
                    ? 'bg-primary text-white border-primary shadow-lg shadow-primary/25 scale-105' 
                    : 'bg-card text-gray-400 border-gray-700 hover:bg-gray-700 hover:text-white hover:border-gray-500'}
                `}
              >
                <Icon className={`w-4 h-4 ${isActive ? 'text-white' : 'text-gray-500 group-hover:text-white'} ${category.id === -1 && !isActive ? 'text-primary' : ''}`} />
                {category.name}
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
};

