  const [channel, setChannel] = useState<Channel | null>(null);

  useEffect(() => {
    // 1. Try to find in standard channels list
    const found = channels.find(c => c.id === id);

    if (found) {
      setChannel(found);
      addToHistory(found.id);
    } 
