    const handleKeyDown = (e: KeyboardEvent) => {
      // Ignore if user is typing in an input field (like search)
      const target = e.target as HTMLElement;
      if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA') {
        return;
      }

      // Handle Numbers
      if (/^[0-9]$/.test(e.key)) {
        setInputBuffer(prev => {
          // Limit to 4 digits
          if (prev.length >= 4) return prev;
          return prev + e.key;
        });

        // Reset timer
        if (timeoutRef.current) clearTimeout(timeoutRef.current);
        timeoutRef.current = window.setTimeout(executeChannelSwitch, 2000); // 2 seconds delay
      }

      // Handle Enter (Confirm immediately)
      if (e.key === 'Enter' && inputBuffer) {
        if (timeoutRef.current) clearTimeout(timeoutRef.current);
        executeChannelSwitch();
      }

      // Handle Backspace (Correction)
      if (e.key === 'Backspace') {
        setInputBuffer(prev => prev.slice(0, -1));
        if (timeoutRef.current) clearTimeout(timeoutRef.current);
        if (inputBuffer.length > 1) {
             timeoutRef.current = window.setTimeout(executeChannelSwitch, 2000);
        }
      }

      // Handle Escape (Cancel)
      if (e.key === 'Escape') {
          setInputBuffer("");
          if (timeoutRef.current) clearTimeout(timeoutRef.current);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, [inputBuffer, channels]); // Dependencies for the event listener closure

  const executeChannelSwitch = () => {
    if (!inputBuffer) return;

    const index = parseInt(inputBuffer) - 1;

    // Clear buffer immediately to hide UI
    const currentBuffer = inputBuffer; // Capture for logic
    setInputBuffer("");

    if (index >= 0 && index < channels.length) {
      const channel = channels[index];
      // console.log(`Switching to Channel ${currentBuffer}: ${channel.name}`);
      navigate(`/watch/${channel.id}`);
    } else {
      // console.log(`Channel ${currentBuffer} not found`);
      // Optional: Show "Channel not found" temporary toast
    }
  };

  if (!inputBuffer) return null;

  return (
    <div className="fixed top-20 right-8 z-[100] animate-in fade-in slide-in-from-top-2 duration-300 pointer-events-none select-none">
      <div className="bg-black/80 backdrop-blur-md border border-green-500/30 rounded-lg p-4 shadow-2xl min-w-[200px] flex flex-col gap-2">
        <div className="flex items-center justify-between border-b border-white/10 pb-2">
           <span className="text-green-500 font-mono text-sm uppercase tracking-widest flex items-center gap-2">
             <Tv className="w-4 h-4" /> Canal
           </span>
           <span className="text-4xl font-bold font-mono text-green-400 tracking-tighter drop-shadow-green">
             {inputBuffer}
           </span>
        </div>

        <div className="pt-1">
          {targetChannel ? (
            <div className="text-white font-medium truncate text-lg">
              {targetChannel.name}
            </div>
          ) : (
             <div className="text-red-400 font-mono text-sm">
               Canal não encontrado
             </div>
          )}
        </div>

        <div className="flex items-center gap-1 text-[10px] text-gray-500 uppercase tracking-wider mt-1">
            <CornerDownLeft className="w-3 h-3" />
            <span>Enter para ir</span>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { HashRouter, Routes, Route } from 'react-router-dom';
import { fetchChannels } from './services/dataService';
import { Channel, Category } from './types';
import { Loader2 } from 'lucide-react';
import { Home } from './pages/Home';
import { Watch } from './pages/Watch';
import { RemoteControl } from './components/RemoteControl';

const App: React.FC = () => {
  const [channels, setChannels] = useState<Channel[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [isAppLoading, setIsAppLoading] = useState<boolean>(true);

  // Favorites State with localStorage persistence
  const [favorites, setFavorites] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('favorites');
      return saved ? JSON.parse(saved) : [];
    } catch (e) {
      console.error("Error loading favorites", e);
      return [];
    }
  });

  // History State with localStorage persistence
  const [history, setHistory] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('history');
      return saved ? JSON.parse(saved) : [];
    } catch (e) {
      console.error("Error loading history", e);
      return [];
    }
  });

  const toggleFavorite = (channelId: string) => {
    setFavorites(prev => {
      const newFavs = prev.includes(channelId)
        ? prev.filter(id => id !== channelId)
        : [...prev, channelId];

      localStorage.setItem('favorites', JSON.stringify(newFavs));
      return newFavs;
    });
  };

  const addToHistory = useCallback((channelId: string) => {
    setHistory(prev => {
      // Remove if exists to move to top, limit to 10
      const newHistory = [channelId, ...prev.filter(id => id !== channelId)].slice(0, 10);
      localStorage.setItem('history', JSON.stringify(newHistory));
      return newHistory;
    });
  }, []);

  // Initial Data Fetch
  useEffect(() => {
    const loadData = async () => {
      try {
        const data = await fetchChannels();

        // Inject "Favoritos", "Recentes", and "Jogos" categories
        const todosCat = data.categories.find(c => c.id === 0) || { id: 0, name: "Todos" };
        const otherCats = data.categories.filter(c => c.id !== 0);

        const enhancedCategories = [
          todosCat,
          { id: -3, name: "Jogos" }, // New Games Category
          { id: -1, name: "Favoritos" },
          { id: -2, name: "Recentes" },
          ...otherCats
        ];

        setCategories(enhancedCategories);
        setChannels(data.channels);
      } catch (error) {
        console.error("Failed to load data", error);
      } finally {
        setIsAppLoading(false);
      }
    };
    loadData();
  }, []);

  if (isAppLoading) {
    return (
      <div className="min-h-screen bg-dark flex flex-col items-center justify-center">
        <Loader2 className="w-12 h-12 text-primary animate-spin mb-4" />
        <h1 className="text-xl font-bold text-white tracking-widest">Mega Canais <span className="text-primary">TV</span></h1>
        <p className="text-gray-500 mt-2 text-sm">Carregando programação...</p>
      </div>
    );
  }

  return (
    <HashRouter>
      <div className="min-h-screen bg-dark text-white font-sans relative">
        <RemoteControl channels={channels} />
        <Routes>
          <Route 
            path="/" 
            element={
              <Home 
                channels={channels} 
                categories={categories}
                favorites={favorites}
                toggleFavorite={toggleFavorite}
                history={history}
              />
            } 
          />
          <Route 
            path="/watch/:id" 
            element={<Watch channels={channels} addToHistory={addToHistory} />} 
          />
        </Routes>
      </div>
    </HashRouter>
  );
};

