import { ApiData, Game } from '../types';
import { initialData } from './initialData';

const CACHE_KEY = 'megacanaistv_data_v2';
const CACHE_DURATION = 1000 * 60 * 60; // 1 hour

interface CachedData {
  timestamp: number;
  data: ApiData;
}

// Static Fallback Data removed as requested
const FALLBACK_GAMES: Game[] = [];

export const fetchChannels = async (): Promise<ApiData> => {
  try {
    // 1. Check Local Storage
    const cachedString = localStorage.getItem(CACHE_KEY);

    if (cachedString) {
      try {
        const cached: CachedData = JSON.parse(cachedString);
        const now = Date.now();

        // If cache is valid (less than 1 hour old), return it
        if (now - cached.timestamp < CACHE_DURATION) {
          // console.log("Serving from local cache");
          return Promise.resolve(cached.data);
        }
      } catch (e) {
        console.warn("Cache parse error, refreshing data");
        localStorage.removeItem(CACHE_KEY);
      }
    }

    // 2. Simulate Network Request (Using initialData)
    const freshData = initialData;

    // 3. Save to Cache
    try {
      const cachePayload: CachedData = {
        timestamp: Date.now(),
        data: freshData
      };
      localStorage.setItem(CACHE_KEY, JSON.stringify(cachePayload));
    } catch (e) {
      console.error("Failed to save to cache (quota exceeded?)", e);
    }

    return Promise.resolve(freshData);
  } catch (error) {
    console.error("Failed to fetch channels:", error);
    return {
      categories: [],
      channels: []
    };
  }
};

export const fetchGames = async (): Promise<Game[]> => {
  try {
    const date = new Date();
    const day = String(date.getDate()).padStart(2, '0');
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const year = date.getFullYear();
    const dateString = `${day}${month}${year}`;

    // Updated URL to use the new source provided by the user
    // Direct fetch without proxy as requested
    const targetUrl = `https://megacanaisonline.space/api/scramnpjogos.php?day=${dateString}`;

    const response = await fetch(targetUrl);

    if (!response.ok) {
       throw new Error(`API error: ${response.status}`);
    }

    const data = await response.json();
    if (Array.isArray(data) && data.length > 0) {
      return data;
    }

    return [];

  } catch (error) {
    // Log helpful info for debugging but don't crash app
    console.warn("Could not fetch live games.", error);
    return [];
  }
};

import React, { useState, useEffect, useCallback } from 'react';
import { HashRouter, Routes, Route } from 'react-router-dom';
import { fetchChannels } from './services/dataService';
import { Channel, Category } from './types';
import { Loader2 } from 'lucide-react';
import { Home } from './pages/Home';
import { Watch } from './pages/Watch';
import { RemoteControl } from './components/RemoteControl';

const App: React.FC = () => {
  const [channels, setChannels] = useState<Channel[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [isAppLoading, setIsAppLoading] = useState<boolean>(true);

  // Favorites State with localStorage persistence
  const [favorites, setFavorites] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('favorites');
      return saved ? JSON.parse(saved) : [];
    } catch (e) {
      console.error("Error loading favorites", e);
      return [];
    }
  });

  // History State with localStorage persistence
  const [history, setHistory] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('history');
      return saved ? JSON.parse(saved) : [];
    } catch (e) {
      console.error("Error loading history", e);
      return [];
    }
  });

  const toggleFavorite = (channelId: string) => {
    setFavorites(prev => {
      const newFavs = prev.includes(channelId)
        ? prev.filter(id => id !== channelId)
        : [...prev, channelId];

      localStorage.setItem('favorites', JSON.stringify(newFavs));
      return newFavs;
    });
  };

  const addToHistory = useCallback((channelId: string) => {
    setHistory(prev => {
      // Remove if exists to move to top, limit to 10
      const newHistory = [channelId, ...prev.filter(id => id !== channelId)].slice(0, 10);
      localStorage.setItem('history', JSON.stringify(newHistory));
      return newHistory;
    });
  }, []);

  // Initial Data Fetch
  useEffect(() => {
    const loadData = async () => {
      try {
        const data = await fetchChannels();

        // Inject "Favoritos", "Recentes", and "Jogos" categories
        const todosCat = data.categories.find(c => c.id === 0) || { id: 0, name: "Todos" };
        const otherCats = data.categories.filter(c => c.id !== 0);

        const enhancedCategories = [
          todosCat,
          { id: -3, name: "Futebol Ao vivo" }, // Renamed from Jogos
          { id: -1, name: "Favoritos" },
          { id: -2, name: "Recentes" },
          ...otherCats
        ];

        setCategories(enhancedCategories);
        setChannels(data.channels);
      } catch (error) {
        console.error("Failed to load data", error);
      } finally {
        setIsAppLoading(false);
      }
    };
    loadData();
  }, []);

  if (isAppLoading) {
    return (
      <div className="min-h-screen bg-dark flex flex-col items-center justify-center">
        <Loader2 className="w-12 h-12 text-primary animate-spin mb-4" />
        <h1 className="text-xl font-bold text-white tracking-widest">Mega Canais <span className="text-primary">TV</span></h1>
        <p className="text-gray-500 mt-2 text-sm">Carregando programação...</p>
      </div>
    );
  }

  return (
    <HashRouter>
      <div className="min-h-screen bg-dark text-white font-sans relative">
        <RemoteControl channels={channels} />
        <Routes>
          <Route 
            path="/" 
            element={
              <Home 
                channels={channels} 
                categories={categories}
                favorites={favorites}
                toggleFavorite={toggleFavorite}
                history={history}
              />
            } 
          />
          <Route 
            path="/watch/:id" 
            element={<Watch channels={channels} addToHistory={addToHistory} />} 
          />
        </Routes>
      </div>
    </HashRouter>
  );
};

export default App;

