import { ApiData, Game, Channel, Category } from '../types';
import { initialData } from './initialData';

const CACHE_KEY_DEFAULT = 'megacanaistv_data_v2';
const CACHE_KEY_REI = 'reidoscanais_data_v1';
const SOURCE_KEY = 'content_source'; // 'default' or 'reidoscanais'
const CACHE_DURATION = 1000 * 60 * 60; // 1 hora

interface CachedData {
  timestamp: number;
  data: ApiData;
}

// Helper to map text categories from external API to our internal IDs
const mapCategoryToId = (categoryName: string): number[] => {
  const lowerName = (categoryName || '').toLowerCase();

  // Always include 0 (Todos)
  const ids = [0];

  if (lowerName.includes('bbb')) ids.push(8);
  else if (lowerName.includes('aberta') || lowerName.includes('locais')) ids.push(6);
  else if (lowerName.includes('esporte') || lowerName.includes('futebol')) ids.push(1);
  else if (lowerName.includes('filme') || lowerName.includes('cine') || lowerName.includes('series') || lowerName.includes('séries')) ids.push(4);
  else if (lowerName.includes('24') || lowerName.includes('horas')) ids.push(9);
  else if (lowerName.includes('infantil') || lowerName.includes('kids') || lowerName.includes('desenho')) ids.push(2);
  else if (lowerName.includes('noticia') || lowerName.includes('news') || lowerName.includes('jornal')) ids.push(5);
  else if (lowerName.includes('documentario') || lowerName.includes('animal') || lowerName.includes('discovery')) ids.push(3);
  else if (lowerName.includes('religioso') || lowerName.includes('gospel')) ids.push(10);
  else if (lowerName.includes('musica') || lowerName.includes('clipes')) ids.push(11);
  else ids.push(7); // Variedades fallback

  return ids;
};

// ============================
// BUSCAR CANAIS (ROUTER)
// ============================
export const fetchChannels = async (): Promise<ApiData> => {
  const source = localStorage.getItem(SOURCE_KEY) || 'default';

  if (source === 'reidoscanais') {
    return fetchReiChannels();
  } else {
    return fetchDefaultChannels();
  }
};

// ============================
// 1. FONTE PADRÃO (LOCAL/INITIAL)
// ============================
const fetchDefaultChannels = async (): Promise<ApiData> => {
  try {
    const cachedString = localStorage.getItem(CACHE_KEY_DEFAULT);
    if (cachedString) {
      const cached: CachedData = JSON.parse(cachedString);
      if (Date.now() - cached.timestamp < CACHE_DURATION) {
        return cached.data;
      }
    }

    const freshData = initialData;

    // Save cache
    localStorage.setItem(CACHE_KEY_DEFAULT, JSON.stringify({ timestamp: Date.now(), data: freshData }));
    return freshData;

  } catch (error) {
    console.error("Default source error:", error);
    return initialData;
  }
};

// ============================
// 2. FONTE ALTERNATIVA (API EXTERNA)
// ============================
const fetchReiChannels = async (): Promise<ApiData> => {
  try {
    // Check Cache first
    const cachedString = localStorage.getItem(CACHE_KEY_REI);
    if (cachedString) {
      const cached: CachedData = JSON.parse(cachedString);
      if (Date.now() - cached.timestamp < CACHE_DURATION) {
        return cached.data;
      }
    }

    // Fetch from API
    const response = await fetch('https://api.reidoscanais.io/channels');
    if (!response.ok) throw new Error('Falha na API externa');

    const json = await response.json();

    if (!json.success || !Array.isArray(json.data)) {
      throw new Error('Formato inválido da API externa');
    }

    // Map external structure to internal Channel interface
    const mappedChannels: Channel[] = json.data.map((item: any) => ({
      id: item.id || Math.random().toString(36).substr(2, 9),
      name: item.name || 'Canal Sem Nome',
      image: item.logo_url || '',
      url: item.embed_url || '',
      description: item.description || '',
      categories: mapCategoryToId(item.category),
      currentProgram: item.category // Use category name as program placeholder usually
    }));

    // Use default categories list structure so the UI icons work
    const result: ApiData = {
      categories: initialData.categories,
      channels: mappedChannels
    };

    // Save Cache
    localStorage.setItem(CACHE_KEY_REI, JSON.stringify({ timestamp: Date.now(), data: result }));

    return result;

  } catch (error) {
    console.error("Rei API error:", error);
    alert("Erro ao carregar Fonte Alternativa. Voltando para Padrão.");
    localStorage.setItem(SOURCE_KEY, 'default');
    return fetchDefaultChannels();
  }
};

// ============================
// JOGOS (API REMOTA)
