export const fetchGames = async (): Promise<Game[]> => {
  try {
    const date = new Date();
    const day = String(date.getDate()).padStart(2, '0');
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const year = date.getFullYear();
    const dateString = `${day}${month}${year}`;

    const targetUrl = `https://megacanaisonline.space/api/scramnpjogos.php?day=${dateString}`;

    const response = await fetch(targetUrl);

    if (!response.ok) {
       throw new Error(`API error: ${response.status}`);
    }

    const data = await response.json();

    // Check for different API return styles
    let gamesArray = [];
    if (Array.isArray(data)) {
      gamesArray = data;
    } else if (data && Array.isArray(data.data)) {
        // Adaptation if the API format changes to { status: true, data: [...] }
        // based on previous context, the user provided code suggested simpler array or object
        gamesArray = data.data; 
    } else if (Array.isArray(data.jogos)) {
        gamesArray = data.jogos;
    }

    if (gamesArray.length > 0) {
      // Map to ensure strict typing if necessary, or pass through if structure matches
      return gamesArray.map((item: any) => {
          // Verify structure matches Game interface. 
          // Assuming the new API endpoint returns the exact structure expected by GameList
          // based on previous turn changes.
          return item;
      });
    }

    return [];

  } catch (error) {
    console.warn("Could not fetch live games.", error);
    return [];
  }
};

