                 </div>

                 {/* Away Team */}
                 <div className="flex flex-col items-center flex-1 min-w-0">
                   <div className="w-14 h-14 mb-3 p-1 bg-white/5 rounded-full flex items-center justify-center">
                      <img 
                        src={game.data.teams.away.image} 
                        alt={game.data.teams.away.name} 
                        className="w-full h-full object-contain" 
                        onError={(e) => (e.currentTarget.src = 'https://cdn-icons-png.flaticon.com/512/3135/3135715.png')} 
                      />
                   </div>
                   <span className="text-xs font-bold text-center leading-tight line-clamp-2 w-full">
