export const fetchGames = async (): Promise<Game[]> => {
  // Check source for Games too
  const source = localStorage.getItem(SOURCE_KEY) || 'default';

  if (source === 'reidoscanais') {
    // Alternative Source for Games
    // Currently returns empty because a specific Games API endpoint for 'reidoscanais' wasn't provided.
    // This ensures we don't mix "Default" games with "Alternative" channels.
    // If an endpoint exists (e.g. https://api.reidoscanais.io/games), it should be implemented here.
    return [];
  }

  // Default Source for Games
  try {
    const date = new Date();
    const day = String(date.getDate()).padStart(2, '0');
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const year = date.getFullYear();
    const dateString = `${day}${month}${year}`;

    const targetUrl = `https://megacanaisonline.space/api/scramnpjogos.php?day=${dateString}`;

