                            ? 'Nenhum dispositivo encontrado' 
                            : 'Toque para conectar'
                    )}
                  </p>
                </div>
              </div>
              <ChevronRight className="w-5 h-5 text-gray-400" />
            </div>

            <div className="p-4 bg-gray-50 dark:bg-gray-900/50 flex gap-4 overflow-x-auto">
                <div className="min-w-[100px] p-3 rounded-xl border border-gray-200 dark:border-gray-700 flex flex-col items-center gap-2 text-center">
                    <Smartphone className="w-6 h-6 text-gray-400" />
                    <span className="text-xs font-medium text-gray-500">Este Celular</span>
                </div>
                 <div className={`min-w-[100px] p-3 rounded-xl border-2 border-dashed flex flex-col items-center gap-2 text-center 
                    ${isConnected ? 'border-blue-500/50 bg-blue-500/5' : 'border-gray-200 dark:border-gray-700'}
                 `}>
                    <Wifi className={`w-6 h-6 ${isConnected ? 'text-blue-500' : 'text-gray-400'}`} />
                    <span className="text-xs font-medium text-gray-500">
                        {isConnected ? 'TV Conectada' : 'Buscar TV'}
                    </span>
                </div>
            </div>
          </div>
        </section>

        <div className="flex flex-col items-center justify-center text-center mt-10 text-gray-400 text-sm gap-2">
           <div className="w-12 h-12 bg-gray-200 dark:bg-gray-800 rounded-xl flex items-center justify-center mb-2">
             <ShieldCheck className="w-6 h-6 text-gray-500" />
           </div>
           <p className="font-bold text-gray-600 dark:text-gray-300">Mega Canais TV v2.2.0</p>
        </div>

      </main>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  ArrowLeft, 
  Moon, 
  Sun, 
  Cast, 
  ChevronRight,
  ShieldCheck,
  Smartphone,
  Wifi,
  Loader2
} from 'lucide-react';
import { initializeCastApi, requestSession, getCastContext, endCurrentSession, CAST_STATES } from '../services/castService';

interface SettingsProps {
  isDark: boolean;
  toggleTheme: () => void;
}

export const Settings: React.FC<SettingsProps> = ({ isDark, toggleTheme }) => {
  const navigate = useNavigate();
  const [castState, setCastState] = useState<string>('NO_DEVICES_AVAILABLE');

  useEffect(() => {
    // 1. Initialize Cast
    initializeCastApi();

    // 2. Setup Cast Listeners
    const setupCastListener = () => {
      const context = getCastContext();
      if (context) {
        // Set initial state
        setCastState(context.getCastState());

        // Listen for changes
        const eventHandler = (event: any) => {
          setCastState(event.castState);
        };

        context.addEventListener(
          window.cast.framework.CastContextEventType.CAST_STATE_CHANGED,
          eventHandler
        );

        return () => {
          context.removeEventListener(
            window.cast.framework.CastContextEventType.CAST_STATE_CHANGED,
            eventHandler
          );
        };
      }
    };

    // Retry finding context if it loads slowly
    const timer = setTimeout(setupCastListener, 1000);
    const cleanup = setupCastListener();

    return () => {
      clearTimeout(timer);
      if (cleanup) cleanup();
    };
  }, []);

  const handleCast = async () => {
    // 1. Promoção do App Externo (Solicitação do usuário)
    const wantsApp = window.confirm("Para transmitir para a TV com estabilidade, recomendamos instalar o app 'Cast to TV'. Deseja baixar/abrir agora?");

    if (wantsApp) {
        window.open("https://play.google.com/store/apps/details?id=cast.video.screenmirroring.casttotv&hl=pt_BR", "_blank");
        return;
    }

    // 2. Lógica Nativa (Fallback se o usuário cancelar)
    if (castState === CAST_STATES.NO_DEVICES_AVAILABLE) {
      alert("Nenhum dispositivo Chromecast encontrado na rede pelo navegador.");
      return;
    }

    if (castState === CAST_STATES.CONNECTED) {
        const confirmDisconnect = window.confirm("Desconectar do Chromecast?");
        if (confirmDisconnect) {
            endCurrentSession();
        }
    } else {
        await requestSession();
    }
  };

  const isConnected = castState === CAST_STATES.CONNECTED;
  const isConnecting = castState === CAST_STATES.CONNECTING;

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-dark transition-colors duration-300">
      <header className="bg-white dark:bg-dark border-b border-gray-200 dark:border-gray-800 sticky top-0 z-50">
        <div className="container mx-auto px-4 h-16 flex items-center gap-4">
          <button 
            onClick={() => navigate('/')}
            className="p-2 -ml-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full transition-colors text-gray-800 dark:text-white"
          >
            <ArrowLeft className="w-6 h-6" />
          </button>
          <h1 className="text-xl font-bold text-gray-800 dark:text-white">Configurações</h1>
        </div>
      </header>

      <main className="container mx-auto px-4 py-8 max-w-3xl">

        {/* Appearance */}
        <section className="mb-8">
          <h2 className="text-sm font-bold text-primary uppercase tracking-wider mb-4 px-2">Aparência</h2>
          <div className="bg-white dark:bg-card rounded-2xl shadow-sm border border-gray-200 dark:border-gray-800 overflow-hidden">
            <div 
              className="flex items-center justify-between p-4 cursor-pointer hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors"
              onClick={toggleTheme}
            >
              <div className="flex items-center gap-4">
                <div className={`w-10 h-10 rounded-full flex items-center justify-center ${isDark ? 'bg-purple-500/10 text-purple-400' : 'bg-orange-500/10 text-orange-500'}`}>
                   {isDark ? <Moon className="w-5 h-5" /> : <Sun className="w-5 h-5" />}
                </div>
                <div>
                  <p className="font-semibold text-gray-900 dark:text-white">Tema do Aplicativo</p>
                  <p className="text-sm text-gray-500 dark:text-gray-400">
                    {isDark ? 'Modo Escuro Ativado' : 'Modo Claro Ativado'}
                  </p>
                </div>
              </div>
              <div className={`w-12 h-6 rounded-full p-1 transition-colors duration-300 flex items-center ${isDark ? 'bg-primary justify-end' : 'bg-gray-300 justify-start'}`}>
                <div className="w-4 h-4 rounded-full bg-white shadow-sm"></div>
              </div>
            </div>
          </div>
        </section>

        {/* Transmission - ROBUST */}
        <section className="mb-8">
          <h2 className="text-sm font-bold text-primary uppercase tracking-wider mb-4 px-2">Transmissão & Dispositivos</h2>
          <div className="bg-white dark:bg-card rounded-2xl shadow-sm border border-gray-200 dark:border-gray-800 overflow-hidden">
            <div 
              className={`flex items-center justify-between p-4 border-b border-gray-100 dark:border-gray-800 cursor-pointer transition-colors
                ${isConnected ? 'bg-blue-500/10' : 'hover:bg-gray-50 dark:hover:bg-gray-700/50'}
              `}
              onClick={handleCast}
            >
              <div className="flex items-center gap-4">
                <div className={`w-10 h-10 rounded-full flex items-center justify-center ${isConnected ? 'bg-blue-500 text-white shadow-lg shadow-blue-500/40' : 'bg-blue-500/10 text-blue-500'}`}>
                   {isConnecting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Cast className={`w-5 h-5`} />}
                </div>
                <div>
                  <p className={`font-semibold ${isConnected ? 'text-blue-400' : 'text-gray-900 dark:text-white'}`}>
                    Google Cast / App Parceiro
                  </p>
                  <p className="text-sm text-gray-500 dark:text-gray-400">
                    {isConnected ? 'Conectado à TV' : 'Conectar ou baixar app'}
                  </p>
                </div>
              </div>
              <ChevronRight className="w-5 h-5 text-gray-400" />
            </div>

            <div className="p-4 bg-gray-50 dark:bg-gray-900/50 flex gap-4 overflow-x-auto">
                <div className="min-w-[100px] p-3 rounded-xl border border-gray-200 dark:border-gray-700 flex flex-col items-center gap-2 text-center">
                    <Smartphone className="w-6 h-6 text-gray-400" />
                    <span className="text-xs font-medium text-gray-500">Este Celular</span>
                </div>
                 <div className={`min-w-[100px] p-3 rounded-xl border-2 border-dashed flex flex-col items-center gap-2 text-center 
                    ${isConnected ? 'border-blue-500/50 bg-blue-500/5' : 'border-gray-200 dark:border-gray-700'}
                 `}>
                    <Wifi className={`w-6 h-6 ${isConnected ? 'text-blue-500' : 'text-gray-400'}`} />
                    <span className="text-xs font-medium text-gray-500">
                        {isConnected ? 'TV Conectada' : 'Buscar TV'}
                    </span>
                </div>
            </div>
          </div>
        </section>

        <div className="flex flex-col items-center justify-center text-center mt-10 text-gray-400 text-sm gap-2">
           <div className="w-12 h-12 bg-gray-200 dark:bg-gray-800 rounded-xl flex items-center justify-center mb-2">
             <ShieldCheck className="w-6 h-6 text-gray-500" />
           </div>
           <p className="font-bold text-gray-600 dark:text-gray-300">Mega Canais TV v2.2.0</p>
        </div>

      </main>
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Channel } from '../types';
import { 
  Maximize2, 
  AlertCircle, 
  Loader2, 
  ArrowLeft, 
  Volume2, 
  VolumeX, 
  Expand,
  Minimize2,
  Sparkles,
  ExternalLink,
  Cast
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { generateChannelDescription, Source } from '../services/aiService';
import { castMedia, requestSession, getCastContext, CAST_STATES, initializeCastApi } from '../services/castService';

interface PlayerProps {
  channel: Channel;
}

export const Player: React.FC<PlayerProps> = ({ channel }) => {
  const navigate = useNavigate();
  const [isLoading, setIsLoading] = useState(true);
  const [hasError, setHasError] = useState(false);
  const [iframeKey, setIframeKey] = useState(0);

  // AI Description State
  const [aiDescription, setAiDescription] = useState<string | null>(null);
  const [aiSources, setAiSources] = useState<Source[]>([]);
  const [loadingAi, setLoadingAi] = useState(false);

  // UI States
  const [isCinemaMode, setIsCinemaMode] = useState(false);
  const [showControls, setShowControls] = useState(true);
  const [volume, setVolume] = useState(100);
  const [isMuted, setIsMuted] = useState(false);
  const controlsTimeoutRef = useRef<number | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Cast State
  const [castState, setCastState] = useState<string>('NO_DEVICES_AVAILABLE');

  useEffect(() => {
    // Reset state when channel changes
    setIsLoading(true);
    setHasError(false);
    setIframeKey(prev => prev + 1);

    // Reset AI state
    setAiDescription(null);
    setAiSources([]);

    // Fetch AI Description
    const fetchDescription = async () => {
      setLoadingAi(true);
      const result = await generateChannelDescription(channel.name);
      if (result) {
        setAiDescription(result.text);
        setAiSources(result.sources);
      }
      setLoadingAi(false);
    };

    // Debounce slightly to avoid race conditions on rapid switching
    const timer = setTimeout(fetchDescription, 100);

    // Initialize Cast
    initializeCastApi();
    const setupCast = () => {
        const context = getCastContext();
        if (context) {
            setCastState(context.getCastState());
            const handler = (e: any) => setCastState(e.castState);
            context.addEventListener(window.cast.framework.CastContextEventType.CAST_STATE_CHANGED, handler);
            return () => context.removeEventListener(window.cast.framework.CastContextEventType.CAST_STATE_CHANGED, handler);
        }
    };

    // Try to setup cast listener
    const cleanupCast = setupCast();

    return () => {
        clearTimeout(timer);
        if (cleanupCast) cleanupCast();
    };

  }, [channel]);

  // Clean up timeout on unmount
  useEffect(() => {
    return () => {
      if (controlsTimeoutRef.current) {
        window.clearTimeout(controlsTimeoutRef.current);
      }
    };
  }, []);

  const handleIframeLoad = () => {
    setIsLoading(false);
  };

  const handleFullscreen = () => {
    const playerElement = document.getElementById('video-player-container');
    if (playerElement) {
      if (document.fullscreenElement) {
        document.exitFullscreen();
      } else {
        playerElement.requestFullscreen();
      }
    }
  };

  const toggleCinemaMode = () => {
    setIsCinemaMode(!isCinemaMode);
    // Force show controls when toggling
    setShowControls(true);
    if (controlsTimeoutRef.current) {
      window.clearTimeout(controlsTimeoutRef.current);
    }
    controlsTimeoutRef.current = window.setTimeout(() => {
      if (!isLoading) setShowControls(false);
    }, 3000);
  };

  const handleReload = () => {
    setIsLoading(true);
    setHasError(false);
    setIframeKey(prev => prev + 1);
  };

  const handleBack = () => {
    navigate(-1);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newVol = parseInt(e.target.value);
    setVolume(newVol);
    if (newVol > 0 && isMuted) setIsMuted(false);
    if (newVol === 0) setIsMuted(true);
  };

  const toggleMute = () => {
    setIsMuted(!isMuted);
    if (isMuted && volume === 0) setVolume(50);
  };

  // Interaction handlers for showing/hiding controls
  const handleInteraction = useCallback(() => {
    setShowControls(true);
    if (controlsTimeoutRef.current) {
      window.clearTimeout(controlsTimeoutRef.current);
    }
    controlsTimeoutRef.current = window.setTimeout(() => {
      if (!isLoading) {
        setShowControls(false);
      }
    }, 3000);
  }, [isLoading]);

  const handleCastClick = async () => {
    // 1. Promoção do App Externo (Solicitação)
    const wantsApp = window.confirm("Para transmitir este canal, recomendamos utilizar o app 'Cast to TV'. Deseja baixar/abrir agora?");

    if (wantsApp) {
        window.open("https://play.google.com/store/apps/details?id=cast.video.screenmirroring.casttotv&hl=pt_BR", "_blank");
        return;
    }

    // 2. Lógica Nativa (Fallback)
    if (castState === CAST_STATES.NO_DEVICES_AVAILABLE) {
        alert("Nenhum dispositivo Chromecast encontrado.");
        return;
    }

    if (castState === CAST_STATES.CONNECTED) {
        // Já está conectado, apenas manda a mídia
        castMedia(channel.url, channel.name, channel.image);
    } else {
        // Tenta conectar (User Gesture required)
        const connected = await requestSession();
        if (connected) {
            // Pequeno delay para garantir que a sessão está pronta antes de carregar
            setTimeout(() => {
                castMedia(channel.url, channel.name, channel.image);
            }, 500);
        }
    }
  };

  const isCastConnected = castState === CAST_STATES.CONNECTED;

  return (
    <div className={`transition-all duration-500 ${
      isCinemaMode 
        ? 'fixed inset-0 z-50 bg-black flex flex-col justify-center' 
        : 'w-full bg-dark pt-4 pb-6 relative'
    }`}>
      <div 
        className={`mx-auto transition-all duration-500 ${
          isCinemaMode 
            ? 'w-full h-full' 
            : 'container px-4 max-w-6xl'
        }`}
      >
        {/* Header Section - Hidden in Cinema Mode */}
        {!isCinemaMode && (
          <div className="flex items-center gap-4 mb-4 text-white">
               <button 
                  onClick={handleBack}
                  className="p-2 hover:bg-white/10 rounded-full transition-colors flex items-center justify-center"
                  aria-label="Voltar"
               >
                  <ArrowLeft className="w-6 h-6" />
               </button>
               <div>
                  <h2 className="text-xl sm:text-2xl font-bold leading-tight line-clamp-1">{channel.name}</h2>
                  <div className="flex items-center gap-2">
                    <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                    <p className="text-sm text-gray-300 font-medium">
                      {channel.currentProgram || "Transmissão Ao Vivo"}
                    </p>
                  </div>
               </div>
          </div>
        )}

        {/* Player Container */}
        <div 
          id="video-player-container" 
          ref={containerRef}
          className={`
            relative bg-black overflow-hidden group
            ${isCinemaMode 
              ? `w-full h-full ${!showControls ? 'cursor-none' : 'cursor-default'}` 
              : 'rounded-xl aspect-video w-full shadow-2xl ring-1 ring-white/10'
            }
          `}
          onMouseMove={handleInteraction}
          onClick={handleInteraction}
          onTouchStart={handleInteraction}
        >
          {isLoading && (
            <div className="absolute inset-0 flex flex-col items-center justify-center bg-gray-900 z-10 text-white">
              <Loader2 className="w-12 h-12 animate-spin text-primary mb-3" />
              <p className="text-base font-medium text-gray-300">Carregando sinal...</p>
            </div>
          )}

          {hasError ? (
             <div className="absolute inset-0 flex flex-col items-center justify-center bg-gray-900 z-20 text-white p-4 text-center">
               <AlertCircle className="w-16 h-16 text-red-500 mb-4" />
               <p className="text-xl font-bold mb-2">Sinal Indisponível</p>
               <p className="text-gray-400 text-base mb-6 max-w-md">
                 Não foi possível conectar ao servidor de streaming deste canal. Tente recarregar.
               </p>
               <button 
                 onClick={handleReload}
                 className="px-8 py-3 bg-primary hover:bg-red-600 rounded-full font-bold transition-colors shadow-lg shadow-primary/20"
               >
                 Tentar Novamente
               </button>
             </div>
          ) : (
            <iframe
              key={iframeKey}
              src={channel.url}
              className="w-full h-full border-0"
              allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
              allowFullScreen
              sandbox="allow-forms allow-scripts allow-same-origin allow-presentation"
              onLoad={handleIframeLoad}
              title={`Player ${channel.name}`}
            />
          )}

          {/* Top Overlay for Cinema Mode Info & Exit */}
          {isCinemaMode && (
             <div className={`
                absolute top-0 left-0 right-0 p-4 bg-gradient-to-b from-black/80 to-transparent 
                transition-opacity duration-300 flex justify-between items-start pointer-events-none
                ${showControls ? 'opacity-100' : 'opacity-0'}
             `}>
                <div className="flex items-center gap-3 pointer-events-auto">
                   <button onClick={toggleCinemaMode} className="p-2 bg-black/40 hover:bg-white/20 rounded-full text-white backdrop-blur-sm transition-colors">
                      <ArrowLeft className="w-6 h-6" />
                   </button>
                   <div>
                     <h2 className="text-lg font-bold text-white drop-shadow-md">{channel.name}</h2>
                     <div className="flex items-center gap-2">
                        <span className="w-1.5 h-1.5 bg-green-500 rounded-full"></span>
                        <p className="text-xs text-gray-300 font-medium">{channel.currentProgram || "Ao Vivo"}</p>
                     </div>
                   </div>
                </div>

                <button 
                   onClick={toggleCinemaMode}
                   className="pointer-events-auto flex items-center gap-2 px-4 py-2 bg-primary/90 hover:bg-primary text-white rounded-lg backdrop-blur-sm shadow-lg transition-all"
                >
                   <Minimize2 className="w-4 h-4" />
                   <span className="font-bold text-sm">Sair do Cinema</span>
                </button>
             </div>
          )}

          {/* Bottom Controls Overlay */}
          <div 
            className={`
              absolute bottom-0 left-0 right-0 p-4 bg-gradient-to-t from-black/90 via-black/50 to-transparent 
              transition-opacity duration-300 flex items-end justify-between gap-4
              ${showControls || isLoading ? 'opacity-100' : 'opacity-0'}
            `}
          >
             {/* Left Controls (Volume) */}
             <div className="flex items-center gap-3">
                <div className="flex items-center gap-2 group/vol bg-black/40 backdrop-blur-sm p-2 rounded-lg hover:bg-black/60 transition-colors pointer-events-auto">
                  <button onClick={toggleMute} className="text-white hover:text-primary transition-colors">
                    {isMuted || volume === 0 ? <VolumeX className="w-5 h-5" /> : <Volume2 className="w-5 h-5" />}
                  </button>
                  <div className="w-0 overflow-hidden group-hover/vol:w-24 transition-all duration-300 ease-out flex items-center">
                    <input 
                      type="range" 
                      min="0" 
                      max="100" 
                      value={isMuted ? 0 : volume} 
                      onChange={handleVolumeChange} 
                      className="h-1 w-20 bg-gray-600 rounded-lg appearance-none cursor-pointer accent-primary" 
                    />
                  </div>
                </div>
             </div>

             {/* Right Controls (Modes) */}
             <div className="flex items-center gap-2 pointer-events-auto">
                {/* Cast Button - Always Visible to prompt App Install */}
                 <button 
                   onClick={handleCastClick}
                   className={`p-2.5 backdrop-blur-sm rounded-lg transition-colors ${
                     isCastConnected 
                       ? 'bg-blue-600 text-white hover:bg-blue-700' 
                       : 'text-white bg-black/40 hover:bg-blue-600'
                   }`}
                   title={isCastConnected ? "Conectado (Toque para transmitir)" : "Transmitir para TV"}
                 >
                   <Cast className="w-5 h-5" />
                 </button>

               <button 
                 onClick={toggleCinemaMode}
                 className="p-2.5 text-white bg-black/40 backdrop-blur-sm hover:bg-black/60 rounded-lg transition-colors flex items-center gap-2"
                 title={isCinemaMode ? "Sair do Modo Cinema" : "Modo Cinema"}
               >
                 {isCinemaMode ? <Minimize2 className="w-5 h-5" /> : <Expand className="w-5 h-5" />}
                 <span className={`text-xs font-bold ${isCinemaMode ? 'hidden' : 'hidden sm:block'}`}>Cinema</span>
               </button>

               <button 
                 onClick={handleFullscreen}
                 className="p-2.5 text-white bg-black/40 backdrop-blur-sm hover:bg-primary rounded-lg transition-colors"
                 title="Tela Cheia"
               >
                 <Maximize2 className="w-5 h-5" />
               </button>
             </div>
          </div>
        </div>

        {/* Footer Info & AI Description - Only visible when NOT in Cinema Mode */}
        {!isCinemaMode && (
          <div className="mt-6 p-5 bg-card rounded-xl border border-gray-800 shadow-lg">
             <div className="flex flex-col gap-4">

               {/* Header Info */}
               <div>
                 <div className="flex items-center gap-2 mb-2">
                    <h3 className="text-lg font-semibold text-white">Sobre o Canal</h3>
                    {loadingAi && <Loader2 className="w-4 h-4 text-primary animate-spin" />}
                 </div>

                 {/* AI Content */}
                 <div className="relative">
                   {aiDescription ? (
                     <div className="prose prose-invert max-w-none">
                       <div className="flex gap-2 items-start">
                         <Sparkles className="w-5 h-5 text-yellow-500 mt-1 flex-shrink-0" />
                         <p className="text-gray-300 text-base leading-relaxed">
                           {aiDescription}
                         </p>
                       </div>
                     </div>
                   ) : (
                     <p className="text-gray-400 text-sm italic">
                       {loadingAi ? 'Gerando descrição inteligente...' : (channel.description || `Assistindo ${channel.name} ao vivo.`)}
                     </p>
                   )}
                 </div>
               </div>

               {/* Grounding Sources */}
               {aiSources.length > 0 && (
                 <div className="mt-2 pt-3 border-t border-gray-700/50">
                   <p className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-2">Fontes Verificadas</p>
                   <div className="flex flex-wrap gap-2">
                     {aiSources.slice(0, 3).map((source, idx) => (
                       <a 
                         key={idx}
                         href={source.uri}
                         target="_blank"
                         rel="noopener noreferrer"
                         className="flex items-center gap-1.5 px-3 py-1.5 bg-gray-800 hover:bg-gray-700 rounded-full text-xs text-blue-400 hover:text-blue-300 transition-colors border border-gray-700"
                       >
                         <ExternalLink className="w-3 h-3" />
                         <span className="truncate max-w-[150px]">{source.title}</span>
                       </a>
                     ))}
                   </div>
                 </div>
               )}

               <div className="flex gap-4 pt-2">
                  <button onClick={() => setHasError(true)} className="text-sm text-red-400 hover:text-red-300 underline flex items-center gap-1">
                    <AlertCircle className="w-4 h-4" /> Informar problema no vídeo
                  </button>
               </div>

             </div>
          </div>
        )}
      </div>
    </div>
  );
};

