        )}
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Header } from '../components/Header';
import { CategoryList } from '../components/CategoryList';
import { ChannelGrid } from '../components/ChannelGrid';
import { GameList } from '../components/GameList';
import { RadioList } from '../components/RadioList';
import { Channel, Category, Game, Radio } from '../types';
import { fetchGames } from '../services/dataService';

interface HomeProps {
  channels: Channel[];
  categories: Category[];
  favorites: string[];
  toggleFavorite: (id: string) => void;
  history: string[];
  radios: Radio[];
}

export const Home: React.FC<HomeProps> = ({ channels, categories, favorites, toggleFavorite, history, radios }) => {
  const navigate = useNavigate();
  const [activeCategoryId, setActiveCategoryId] = useState<number>(0);
  const [searchQuery, setSearchQuery] = useState<string>("");

  // Games State
  const [games, setGames] = useState<Game[]>([]);
  const [loadingGames, setLoadingGames] = useState<boolean>(false);
  const [gamesLoaded, setGamesLoaded] = useState<boolean>(false);

  // Fetch games when category is selected
  useEffect(() => {
    if (activeCategoryId === -3 && !gamesLoaded) {
      setLoadingGames(true);
      fetchGames()
        .then(data => {
          setGames(data);
          setGamesLoaded(true);
        })
        .finally(() => setLoadingGames(false));
    }
  }, [activeCategoryId, gamesLoaded]);

  // Filter Logic for Channels
  const filteredChannels = useMemo(() => {
    // If we are in "Jogos" or "Rádios" mode, channel filtering doesn't matter much for the main grid
    if (activeCategoryId === -3 || activeCategoryId === -4) return [];

    let result: Channel[] = [];

    if (activeCategoryId === -2) {
      // Recentes: Map history IDs to channels to preserve order (newest first)
      result = history
        .map(id => channels.find(c => c.id === id))
        .filter((c): c is Channel => !!c);
    } else {
      // Standard Filtering
      result = channels.filter((channel) => {
        // Category Logic
        if (activeCategoryId === 0) return true; // Todos
        if (activeCategoryId === -1) {
          // Favoritos
          return favorites.includes(channel.id);
        }
        return channel.categories.includes(activeCategoryId);
      });
    }

    // Apply Search on top of category result
    if (searchQuery) {
      result = result.filter(channel => 
        channel.name.toLowerCase().includes(searchQuery.toLowerCase())
      );
    }

    return result;
  }, [channels, activeCategoryId, searchQuery, favorites, history]);

  // Filter Logic for Games (Search only)
  const filteredGames = useMemo(() => {
    if (activeCategoryId !== -3) return [];
    if (!searchQuery) return games;

    const query = searchQuery.toLowerCase();

    return games.filter(g => {
        // Safe optional chaining to prevent crashes on bad data
        const titleMatch = g.title && g.title.toLowerCase().includes(query);
        const leagueMatch = g.data?.league && g.data.league.toLowerCase().includes(query);
        const homeMatch = g.data?.teams?.home?.name && g.data.teams.home.name.toLowerCase().includes(query);
        const awayMatch = g.data?.teams?.away?.name && g.data.teams.away.name.toLowerCase().includes(query);

        return titleMatch || leagueMatch || homeMatch || awayMatch;
    });
  }, [games, activeCategoryId, searchQuery]);

  // Filter Logic for Radios
  const filteredRadios = useMemo(() => {
    if (activeCategoryId !== -4) return [];
    if (!searchQuery) return radios;

    const query = searchQuery.toLowerCase();
    return radios.filter(r => 
        r.name.toLowerCase().includes(query) || 
        r.city.toLowerCase().includes(query) ||
        r.category.toLowerCase().includes(query)
    );
  }, [radios, activeCategoryId, searchQuery]);

  const handleChannelSelect = (channel: Channel) => {
    navigate(`/watch/${channel.id}`);
  };

  const handleCategorySelect = (id: number) => {
    setActiveCategoryId(id);
    setSearchQuery(""); // Clear search on category change
  };

  return (
    <div className="flex-1 flex flex-col">
      <Header 
        searchTerm={searchQuery} 
        onSearch={setSearchQuery}
      />

      <CategoryList 
        categories={categories} 
        activeCategoryId={activeCategoryId} 
        onSelectCategory={handleCategorySelect} 
      />

      <div className="flex-1">
        <div className="container mx-auto px-4 py-4">
           <div className="flex items-center gap-2 mb-2">
              <div className="w-1 h-6 bg-primary rounded-full"></div>
              <h2 className="text-xl font-bold text-white">
                {categories.find(c => c.id === activeCategoryId)?.name || 'Canais'}
                {searchQuery && <span className="text-gray-400 font-normal text-base ml-2">- Buscando por "{searchQuery}"</span>}
              </h2>
           </div>

           {activeCategoryId === -3 ? (
             <GameList games={filteredGames} loading={loadingGames} />
           ) : activeCategoryId === -4 ? (
             <RadioList radios={filteredRadios} />
           ) : (
             <ChannelGrid 
               channels={filteredChannels} 
               onSelectChannel={handleChannelSelect}
               favorites={favorites}
               onToggleFavorite={toggleFavorite}
             />
           )}
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { useParams, useNavigate, useLocation } from 'react-router-dom';
import { Player } from '../components/Player';
import { Channel, Radio } from '../types';
import { Tv } from 'lucide-react';

interface WatchProps {
  channels: Channel[];
  radios: Radio[];
  addToHistory: (id: string) => void;
}

export const Watch: React.FC<WatchProps> = ({ channels, radios, addToHistory }) => {
  const { id } = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const [channel, setChannel] = useState<Channel | null>(null);

  useEffect(() => {
    // 1. Try to find in standard channels list
    const foundChannel = channels.find(c => c.id === id);

    if (foundChannel) {
      setChannel(foundChannel);
      addToHistory(foundChannel.id);
      return;
    }

    // 2. Try to find in radios list
    const foundRadio = radios.find(r => r.id === id);
    if (foundRadio) {
      // Convert Radio to Channel object for Player
      const radioAsChannel: Channel = {
          id: foundRadio.id,
          name: foundRadio.name,
          image: foundRadio.image,
          categories: [-4],
          url: foundRadio.url,
          description: `${foundRadio.city} - ${foundRadio.category}`,
          currentProgram: "Rádio Ao Vivo"
      };
      setChannel(radioAsChannel);
      // We might want to add radios to history too? For now, yes.
      // Note: addToHistory expects a string ID. It relies on the ID being in the 'channels' list 
      // for the Home history filter to work (since filtering looks up by ID in 'channels').
      // Since radios aren't in 'channels', they won't show up in the history list on Home unless we handle that.
      // For now, let's skip adding radios to history to avoid blank entries.
      return;
    }

    // 3. Check if channel object was passed via navigation state (e.g. from Games)
    if (location.state && location.state.channel) {
      const stateChannel = location.state.channel as Channel;
      // Ensure the ID matches (basic validation)
      if (stateChannel.id === id) {
        setChannel(stateChannel);
      } else {
        navigate('/', { replace: true });
      }
    }
    // 4. Fallback: redirect if not found and data is loaded
    else if (channels.length > 0 && radios.length > 0) {
      navigate('/', { replace: true });
    }
  }, [id, channels, radios, navigate, addToHistory, location.state]);

  if (!channel) {
    return (
      <div className="min-h-screen bg-dark flex flex-col items-center justify-center text-white">
        <p>Carregando...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-dark flex flex-col">
       {/* Minimal Header for Watch Page */}
      <header className="bg-dark border-b border-gray-800">
        <div className="container mx-auto px-4 py-3 flex items-center justify-center sm:justify-between">
          <div className="flex items-center gap-2 cursor-pointer hover:opacity-80 transition-opacity" onClick={() => navigate('/')}>
            <div className="w-8 h-8 bg-primary rounded-lg flex items-center justify-center">
              <Tv className="text-white w-5 h-5" />
            </div>
            <span className="text-lg font-bold tracking-tight">
              Mega Canais <span className="text-primary">TV</span>
            </span>
          </div>
        </div>
      </header>

      <main className="flex-1 flex flex-col">
        <Player channel={channel} />
      </main>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { HashRouter, Routes, Route } from 'react-router-dom';
import { fetchChannels, fetchRadios } from './services/dataService';
import { Channel, Category, Radio } from './types';
import { Loader2 } from 'lucide-react';
import { Home } from './pages/Home';
import { Watch } from './pages/Watch';
import { Settings } from './pages/Settings';
import { RemoteControl } from './components/RemoteControl';

const App: React.FC = () => {
  const [channels, setChannels] = useState<Channel[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [radios, setRadios] = useState<Radio[]>([]);
  const [isAppLoading, setIsAppLoading] = useState<boolean>(true);

  // Theme State
  const [isDark, setIsDark] = useState<boolean>(() => {
    try {
      const saved = localStorage.getItem('theme');
      return saved ? saved === 'dark' : true; // Default to dark
    } catch {
      return true;
    }
  });

  // Apply Theme
  useEffect(() => {
    if (isDark) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDark]);

  const toggleTheme = () => setIsDark(!isDark);

  // Favorites State with localStorage persistence
  const [favorites, setFavorites] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('favorites');
      return saved ? JSON.parse(saved) : [];
    } catch (e) {
      console.error("Error loading favorites", e);
      return [];
    }
  });

  // History State with localStorage persistence
  const [history, setHistory] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('history');
      return saved ? JSON.parse(saved) : [];
    } catch (e) {
      console.error("Error loading history", e);
      return [];
    }
  });

  const toggleFavorite = (channelId: string) => {
    setFavorites(prev => {
      const newFavs = prev.includes(channelId)
        ? prev.filter(id => id !== channelId)
        : [...prev, channelId];

      localStorage.setItem('favorites', JSON.stringify(newFavs));
      return newFavs;
    });
  };

  const addToHistory = useCallback((channelId: string) => {
    setHistory(prev => {
      // Remove if exists to move to top, limit to 10
      const newHistory = [channelId, ...prev.filter(id => id !== channelId)].slice(0, 10);
      localStorage.setItem('history', JSON.stringify(newHistory));
      return newHistory;
    });
  }, []);

  // Initial Data Fetch
  useEffect(() => {
    const loadData = async () => {
      try {
        const [channelsData, radiosData] = await Promise.all([
          fetchChannels(),
          fetchRadios()
        ]);

        // Inject "Favoritos", "Recentes", "Futebol" and "Rádios" categories
        const todosCat = channelsData.categories.find(c => c.id === 0) || { id: 0, name: "Todos" };
        const otherCats = channelsData.categories.filter(c => c.id !== 0);

        const enhancedCategories = [
          todosCat,
          { id: -3, name: "Futebol Ao vivo" },
          { id: -4, name: "Rádios Online" },
          { id: -1, name: "Favoritos" },
          { id: -2, name: "Recentes" },
          ...otherCats
        ];

        setCategories(enhancedCategories);
        setChannels(channelsData.channels);
        setRadios(radiosData);
      } catch (error) {
        console.error("Failed to load data", error);
      } finally {
        setIsAppLoading(false);
      }
    };
    loadData();
  }, []);

  if (isAppLoading) {
    return (
      <div className="min-h-screen bg-dark flex flex-col items-center justify-center">
        <Loader2 className="w-12 h-12 text-primary animate-spin mb-4" />
        <h1 className="text-xl font-bold text-white tracking-widest">Mega Canais <span className="text-primary">TV</span></h1>
        <p className="text-gray-500 mt-2 text-sm">Carregando programação...</p>
      </div>
    );
  }

  return (
    <HashRouter>
      <div className="min-h-screen bg-white dark:bg-dark text-gray-900 dark:text-white font-sans relative transition-colors duration-300">
        <RemoteControl channels={channels} />
        <Routes>
          <Route 
            path="/" 
            element={
              <Home 
                channels={channels} 
                categories={categories}
                favorites={favorites}
                toggleFavorite={toggleFavorite}
                history={history}
                radios={radios}
              />
            } 
          />
          <Route 
            path="/watch/:id" 
            element={<Watch channels={channels} radios={radios} addToHistory={addToHistory} />} 
          />
          <Route 
            path="/settings" 
            element={<Settings isDark={isDark} toggleTheme={toggleTheme} />} 
          />
        </Routes>
      </div>
    </HashRouter>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Channel } from '../types';
import { 
  Maximize2, 
  AlertCircle, 
  Loader2, 
  ArrowLeft, 
  Volume2, 
  VolumeX, 
  Expand,
  Minimize2,
  Sparkles,
  ExternalLink,
  Cast,
  Radio,
  Music2,
  Play,
  Pause
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { generateChannelDescription, Source } from '../services/aiService';
import { castMedia, requestSession, getCastContext, CAST_STATES, initializeCastApi } from '../services/castService';
import { InstallAppModal } from './InstallAppModal';

interface PlayerProps {
  channel: Channel;
}

export const Player: React.FC<PlayerProps> = ({ channel }) => {
  const navigate = useNavigate();
  const [isLoading, setIsLoading] = useState(true);
  const [hasError, setHasError] = useState(false);
  const [iframeKey, setIframeKey] = useState(0);

  // AI Description State
  const [aiDescription, setAiDescription] = useState<string | null>(null);
  const [aiSources, setAiSources] = useState<Source[]>([]);
  const [loadingAi, setLoadingAi] = useState(false);

  // UI States
  const [isCinemaMode, setIsCinemaMode] = useState(false);
  const [showControls, setShowControls] = useState(true);
  const [volume, setVolume] = useState(100);
  const [isMuted, setIsMuted] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false); // New state for Play/Pause

  const controlsTimeoutRef = useRef<number | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Audio Ref
  const audioRef = useRef<HTMLAudioElement>(null);

  // Cast State
  const [castState, setCastState] = useState<string>('NO_DEVICES_AVAILABLE');
  const [showInstallModal, setShowInstallModal] = useState(false);

  const isRadio = channel.categories.includes(-4);

  useEffect(() => {
    // Reset state when channel changes
    setIsLoading(true);
    setHasError(false);
    setIframeKey(prev => prev + 1);
    setIsPlaying(false);

    // Reset AI state
    setAiDescription(null);
    setAiSources([]);

    // Fetch AI Description (Skip for radios usually)
    const fetchDescription = async () => {
      setLoadingAi(true);
      const result = await generateChannelDescription(channel.name);
      if (result) {
        setAiDescription(result.text);
        setAiSources(result.sources);
      }
      setLoadingAi(false);
    };

    // Debounce slightly to avoid race conditions on rapid switching
    const timer = setTimeout(fetchDescription, 100);

    // Initialize Cast
    initializeCastApi();
    const setupCast = () => {
        const context = getCastContext();
        if (context) {
            setCastState(context.getCastState());
            const handler = (e: any) => setCastState(e.castState);
            context.addEventListener(window.cast.framework.CastContextEventType.CAST_STATE_CHANGED, handler);
            return () => context.removeEventListener(window.cast.framework.CastContextEventType.CAST_STATE_CHANGED, handler);
        }
    };

    // Try to setup cast listener
    const cleanupCast = setupCast();

    return () => {
        clearTimeout(timer);
        if (cleanupCast) cleanupCast();
    };

  }, [channel]);

  // Handle Audio Volume
  useEffect(() => {
    if (audioRef.current) {
        audioRef.current.volume = volume / 100;
        audioRef.current.muted = isMuted;
    }
  }, [volume, isMuted]);

  // Clean up timeout on unmount
  useEffect(() => {
    return () => {
      if (controlsTimeoutRef.current) {
        window.clearTimeout(controlsTimeoutRef.current);
      }
    };
  }, []);

  const handleMediaLoad = () => {
    setIsLoading(false);
    if (isRadio && audioRef.current) {
        // Attempt to play and update state
        const playPromise = audioRef.current.play();
        if (playPromise !== undefined) {
            playPromise.then(() => {
                setIsPlaying(true);
            }).catch(error => {
                console.log("Autoplay prevented:", error);
                setIsPlaying(false);
            });
        }
    }
  };

  const togglePlay = (e?: React.MouseEvent) => {
      e?.stopPropagation();
      if (audioRef.current) {
          if (isPlaying) {
              audioRef.current.pause();
              setIsPlaying(false);
          } else {
              audioRef.current.play();
              setIsPlaying(true);
          }
      }
  };

  const handleFullscreen = () => {
    const playerElement = document.getElementById('video-player-container');
    if (playerElement) {
      if (document.fullscreenElement) {
        document.exitFullscreen();
      } else {
        playerElement.requestFullscreen();
      }
    }
  };

  const toggleCinemaMode = () => {
    setIsCinemaMode(!isCinemaMode);
    // Force show controls when toggling
    setShowControls(true);
    if (controlsTimeoutRef.current) {
      window.clearTimeout(controlsTimeoutRef.current);
    }
    controlsTimeoutRef.current = window.setTimeout(() => {
      if (!isLoading) setShowControls(false);
    }, 3000);
  };

  const handleReload = () => {
    setIsLoading(true);
    setHasError(false);
    setIframeKey(prev => prev + 1);
    if (audioRef.current) {
        audioRef.current.load();
        audioRef.current.play().then(() => setIsPlaying(true)).catch(() => setIsPlaying(false));
    }
  };

  const handleBack = () => {
    navigate(-1);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newVol = parseInt(e.target.value);
    setVolume(newVol);
    if (newVol > 0 && isMuted) setIsMuted(false);
    if (newVol === 0) setIsMuted(true);
  };

  const toggleMute = () => {
    setIsMuted(!isMuted);
    if (isMuted && volume === 0) setVolume(50);
  };

  // Interaction handlers for showing/hiding controls
  const handleInteraction = useCallback(() => {
    setShowControls(true);
    if (controlsTimeoutRef.current) {
      window.clearTimeout(controlsTimeoutRef.current);
    }
    controlsTimeoutRef.current = window.setTimeout(() => {
      if (!isLoading && (isPlaying || !isRadio)) { 
          // Only hide if playing (or if it's video mode)
          // If radio is paused, keep controls visible
          setShowControls(false);
      }
    }, 3000);
  }, [isLoading, isPlaying, isRadio]);

  const handleCastClick = () => {
    setShowInstallModal(true);
  };

  const handleInstallApp = () => {
      window.open("https://play.google.com/store/apps/details?id=cast.video.screenmirroring.casttotv&hl=pt_BR", "_blank");
      setShowInstallModal(false);
  };

  const handleNativeCast = async () => {
    setShowInstallModal(false);

    // Fallback logic
    if (castState === CAST_STATES.NO_DEVICES_AVAILABLE) {
        alert("Nenhum dispositivo Chromecast encontrado.");
        return;
    }

    if (castState === CAST_STATES.CONNECTED) {
        // Já está conectado, apenas manda a mídia
        castMedia(channel.url, channel.name, channel.image);
    } else {
        // Tenta conectar (User Gesture required)
        const connected = await requestSession();
        if (connected) {
            // Pequeno delay para garantir que a sessão está pronta antes de carregar
            setTimeout(() => {
