import { EPGChannel, EPGProgram } from '../types';

// URL fornecida pelo usuário
// Nota: Usamos 'allorigins' como proxy para evitar erros de CORS (Cross-Origin Resource Sharing)
// e erros de Mixed Content (HTTP vs HTTPS), já que a URL original é HTTP.
const EPG_URL = 'http://nocable.cc:8080/xmltv.php?username=J0WfUK&password=016294';
const CORS_PROXY = 'https://api.allorigins.win/raw?url=';

export const fetchEPG = async (): Promise<EPGChannel[]> => {
  try {
    const response = await fetch(`${CORS_PROXY}${encodeURIComponent(EPG_URL)}`);
    if (!response.ok) throw new Error('Falha ao baixar XMLTV');

    const xmlText = await response.text();
    const parser = new DOMParser();
    const xmlDoc = parser.parseFromString(xmlText, "text/xml");

    const epgChannels: EPGChannel[] = [];

    // 1. Parse Channels
    const channelElements = xmlDoc.getElementsByTagName('channel');
    const channelMap = new Map<string, EPGChannel>();

    for (let i = 0; i < channelElements.length; i++) {
      const el = channelElements[i];
      const id = el.getAttribute('id');
      const displayName = el.getElementsByTagName('display-name')[0]?.textContent || '';

      if (id) {
        const channelObj: EPGChannel = {
          id,
          displayName,
          programs: []
        };
        epgChannels.push(channelObj);
        channelMap.set(id, channelObj);
      }
    }

    // 2. Parse Programmes
    const programElements = xmlDoc.getElementsByTagName('programme');
    const now = new Date();
    // Otimização: Pegar apenas programas de hoje/agora
    const todayStr = now.toISOString().slice(0, 10).replace(/-/g, '');

    for (let i = 0; i < programElements.length; i++) {
      const el = programElements[i];
      const channelId = el.getAttribute('channel');

      if (channelId && channelMap.has(channelId)) {
        const startRaw = el.getAttribute('start') || '';
        const stopRaw = el.getAttribute('stop') || '';

        // Parse XMLTV Date: YYYYMMDDHHMMSS +0000
        const parseDate = (dateStr: string) => {
            if (!dateStr) return new Date();
            const year = dateStr.substring(0, 4);
            const month = dateStr.substring(4, 6);
            const day = dateStr.substring(6, 8);
            const hour = dateStr.substring(8, 10);
            const min = dateStr.substring(10, 12);
            const sec = dateStr.substring(12, 14);
            // Assume UTC se tiver +0000, senão assume local (simplificado)
            return new Date(`${year}-${month}-${day}T${hour}:${min}:${sec}`);
        };

        const startDate = parseDate(startRaw);
        const endDate = parseDate(stopRaw);

        // Filtro básico: Ignorar programas que já acabaram há muito tempo (ex: ontem)
        // Mantemos programas atuais e futuros
        if (endDate > new Date(Date.now() - 2 * 60 * 60 * 1000)) { 
             const title = el.getElementsByTagName('title')[0]?.textContent || 'Sem Título';
             const desc = el.getElementsByTagName('desc')[0]?.textContent || '';

             channelMap.get(channelId)?.programs.push({
                 title,
                 description: desc,
                 start: startDate,
                 end: endDate,
                 channelId
             });
        }
      }
    }

    return epgChannels;

  } catch (error) {
    console.error("Erro ao carregar EPG:", error);
    return [];
  }
};

// Helper para encontrar o programa atual dado um canal EPG
export const getCurrentProgram = (epgData: EPGChannel): EPGProgram | null => {
    const now = new Date();
    // Ajuste de Fuso Horário pode ser necessário dependendo do XML. 
    // Assumindo que o XML e o browser estão alinhados ou XML é UTC.
    // O parseDate acima cria um Date object que usa o fuso local se não especificado corretamente.

    // Adicionamos um offset de 3 horas (GMT-3) caso o XML venha como UTC puro mas represente BRT sem offset
    // Ajuste fino pode ser necessário dependendo da fonte exata do XMLTV

    return epgData.programs.find(p => now >= p.start && now < p.end) || null;
};

// Helper para normalizar strings para comparação (Fuzzy match simples)
export const normalizeStr = (str: string) => {
    return str.toLowerCase()
              .normalize("NFD").replace(/[\u0300-\u036f]/g, "") // Remove acentos
              .replace(/[^a-z0-9]/g, "") // Remove caracteres especiais
              .replace("hd", "")
              .replace("fhd", "")
              .replace("br", "");
};

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { fetchEPG, normalizeStr, getCurrentProgram } from '../services/epgService';
import { EPGChannel, CurrentProgramData } from '../types';

interface EPGContextType {
  epgChannels: EPGChannel[];
  loading: boolean;
  getChannelEPG: (channelName: string) => CurrentProgramData | null;
}

const EPGContext = createContext<EPGContextType | undefined>(undefined);

export const EPGProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [epgChannels, setEpgChannels] = useState<EPGChannel[]>([]);
  const [loading, setLoading] = useState(true);

  // Carrega o EPG ao iniciar o app
  useEffect(() => {
    const load = async () => {
      setLoading(true);
      const data = await fetchEPG();
      setEpgChannels(data);
      setLoading(false);
    };
    load();

    // Recarrega a cada 30 minutos para manter atualizado
    const interval = setInterval(load, 30 * 60 * 1000);
    return () => clearInterval(interval);
  }, []);

  // Função inteligente para cruzar o nome do canal do App com o nome do canal no XMLTV
  const getChannelEPG = (channelName: string): CurrentProgramData | null => {
      if (epgChannels.length === 0) return null;

      const target = normalizeStr(channelName);

      // Tenta encontrar o canal no EPG comparando nomes normalizados
      const foundChannel = epgChannels.find(epg => normalizeStr(epg.displayName).includes(target) || target.includes(normalizeStr(epg.displayName)));

      if (foundChannel) {
          const current = getCurrentProgram(foundChannel);
          if (current) {
              const now = new Date().getTime();
              const start = current.start.getTime();
              const end = current.end.getTime();
              const total = end - start;
              const progress = now - start;
              const percentage = Math.min(100, Math.max(0, (progress / total) * 100));

              return {
                  title: current.title,
                  description: current.description,
                  since: current.start.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                  until: current.end.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                  percentage
              };
          }
      }
      return null;
  };

  return (
    <EPGContext.Provider value={{ epgChannels, loading, getChannelEPG }}>
      {children}
    </EPGContext.Provider>
  );
};

export const useEPG = () => {
  const context = useContext(EPGContext);
  if (context === undefined) {
    throw new Error('useEPG must be used within an EPGProvider');
  }
  return context;
};

import React, { useState, useEffect, useCallback } from 'react';
import { HashRouter, Routes, Route } from 'react-router-dom';
import { fetchChannels, fetchRadios } from './services/dataService';
import { Channel, Category, Radio } from './types';
import { Loader2 } from 'lucide-react';
import { Home } from './pages/Home';
import { Watch } from './pages/Watch';
import { Settings } from './pages/Settings';
import { RemoteControl } from './components/RemoteControl';
import { RadioProvider } from './contexts/RadioContext';
import { EPGProvider } from './contexts/EPGContext';
import { GlobalRadioPlayer } from './components/GlobalRadioPlayer';

const App: React.FC = () => {
  const [channels, setChannels] = useState<Channel[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [radios, setRadios] = useState<Radio[]>([]);
  const [isAppLoading, setIsAppLoading] = useState<boolean>(true);

  // Theme State
  const [isDark, setIsDark] = useState<boolean>(() => {
    try {
      const saved = localStorage.getItem('theme');
      return saved ? saved === 'dark' : true; // Default to dark
    } catch {
      return true;
    }
  });

  // Apply Theme
  useEffect(() => {
    if (isDark) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDark]);

  const toggleTheme = () => setIsDark(!isDark);

  // Favorites State with localStorage persistence
  const [favorites, setFavorites] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('favorites');
      return saved ? JSON.parse(saved) : [];
    } catch (e) {
      console.error("Error loading favorites", e);
      return [];
    }
  });

  // History State with localStorage persistence
  const [history, setHistory] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('history');
      return saved ? JSON.parse(saved) : [];
    } catch (e) {
      console.error("Error loading history", e);
      return [];
    }
  });

  const toggleFavorite = (channelId: string) => {
    setFavorites(prev => {
      const newFavs = prev.includes(channelId)
        ? prev.filter(id => id !== channelId)
        : [...prev, channelId];

      localStorage.setItem('favorites', JSON.stringify(newFavs));
      return newFavs;
    });
  };

  const addToHistory = useCallback((channelId: string) => {
    setHistory(prev => {
      // Remove if exists to move to top, limit to 10
      const newHistory = [channelId, ...prev.filter(id => id !== channelId)].slice(0, 10);
      localStorage.setItem('history', JSON.stringify(newHistory));
      return newHistory;
    });
  }, []);

  // Initial Data Fetch
  useEffect(() => {
    const loadData = async () => {
      try {
        const [channelsData, radiosData] = await Promise.all([
          fetchChannels(),
          fetchRadios()
        ]);

        // Inject "Favoritos", "Recentes", "Futebol" and "Rádios" categories
        const todosCat = channelsData.categories.find(c => c.id === 0) || { id: 0, name: "Todos" };
        const otherCats = channelsData.categories.filter(c => c.id !== 0);

        const enhancedCategories = [
          todosCat,
          { id: -3, name: "Futebol Ao vivo" },
          { id: -4, name: "Rádios Online" },
          { id: -1, name: "Favoritos" },
          { id: -2, name: "Recentes" },
          ...otherCats
        ];

        setCategories(enhancedCategories);
        setChannels(channelsData.channels);
        setRadios(radiosData);
      } catch (error) {
        console.error("Failed to load data", error);
      } finally {
        setIsAppLoading(false);
      }
    };
    loadData();
  }, []);

  if (isAppLoading) {
    return (
      <div className="min-h-screen bg-dark flex flex-col items-center justify-center">
        <Loader2 className="w-12 h-12 text-primary animate-spin mb-4" />
        <h1 className="text-xl font-bold text-white tracking-widest">Mega Canais <span className="text-primary">TV</span></h1>
        <p className="text-gray-500 mt-2 text-sm">Carregando programação...</p>
      </div>
    );
  }

  return (
    <EPGProvider>
      <RadioProvider>
        <HashRouter>
          <div className="min-h-screen bg-white dark:bg-dark text-gray-900 dark:text-white font-sans relative transition-colors duration-300">
            <GlobalRadioPlayer />
            <RemoteControl channels={channels} />
            <Routes>
              <Route 
                path="/" 
                element={
                  <Home 
                    channels={channels} 
                    categories={categories}
                    favorites={favorites}
                    toggleFavorite={toggleFavorite}
                    history={history}
                    radios={radios}
                  />
                } 
              />
              <Route 
                path="/watch/:id" 
                element={<Watch channels={channels} radios={radios} addToHistory={addToHistory} />} 
              />
              <Route 
                path="/settings" 
                element={<Settings isDark={isDark} toggleTheme={toggleTheme} />} 
              />
            </Routes>
          </div>
        </HashRouter>
      </RadioProvider>
    </EPGProvider>
  );
};

