  const [activeCategoryId, setActiveCategoryId] = useState<number>(0);
  const [searchQuery, setSearchQuery] = useState<string>("");

  // Games State
  const [games, setGames] = useState<Game[]>([]);
  const [loadingGames, setLoadingGames] = useState<boolean>(false);
  const [gamesLoaded, setGamesLoaded] = useState<boolean>(false);

  // Fetch games when category is selected
  useEffect(() => {
    if (activeCategoryId === -3 && !gamesLoaded) {
      setLoadingGames(true);
      fetchGames()
        .then(data => {
          setGames(data);
          setGamesLoaded(true);
        })
        .finally(() => setLoadingGames(false));
    }
  }, [activeCategoryId, gamesLoaded]);

  const handleCategoryClick = (categoryId: number) => {
    setActiveCategoryId(categoryId);
  };

  const handleSearch = (query: string) => {
    setSearchQuery(query);
  };

  // Filter channels based on search query
  const filteredChannels = channels.filter(channel =>
    channel.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  // Filter radios based on search query
  const filteredRadios = radios.filter(radio =>
    radio.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  // Render content based on active category
  let content;
  if (activeCategoryId === 0) {
    content = filteredChannels.map(channel => (
      <div key={channel.id} onClick={() => navigate(`/watch/${channel.id}`)}>
        {channel.name}
      </div>
    ));
  } else if (activeCategoryId === -1) {
    content = filteredRadios.map(radio => (
      <div key={radio.id} onClick={() => navigate(`/watch/${radio.id}`)}>
        {radio.name}
      </div>
    ));
  } else if (activeCategoryId === -3) {
    content = loadingGames ? (
      <div>Loading Games...</div>
    ) : (
      games.map(game => (
        <div key={game.id} onClick={() => navigate(`/watch/${game.id}`)}>
          {game.name} - {game.time}
        </div>
      ))
    );
  } else if (activeCategoryId === -5) {
    content = <EPGList searchQuery={searchQuery} />;
  } else {
    // Other categories - filter channels by categoryId
    const channelsForCategory = filteredChannels.filter(channel => channel.categoryIds.includes(activeCategoryId));
    content = channelsForCategory.map(channel => (
      <div key={channel.id} onClick={() => navigate(`/watch/${channel.id}`)}>
        {channel.name}
      </div>
    ));
  }

  return (
    <div>
      {/* Category List and Search Bar components here */}
      <input type="text" placeholder="Search..." onChange={e => handleSearch(e.target.value)} />
      {content}
    </div>
  );
};
