export const getCurrentProgram = (
  epgChannel: EPGChannel
): EPGProgram | null => {
  const now = new Date();
  return epgChannel.programs.find(
    (p) => now >= p.start && now < p.end
  ) || null;
};

export const normalizeStr = (str: string): string => {
  return str
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]/g, '')
    .replace('fhd', '')
    .replace('hd', '')
    .replace('4k', '')
    .replace('br', '')
    .trim();
};

