      // Recentes: Map history IDs to channels to preserve order (newest first)
      result = history
        .map(id => channels.find(c => c.id === id))
        .filter((c): c is Channel => !!c);
    } else {
      // Standard Filtering
      result = channels.filter((channel) => {
        // Category Logic
        if (activeCategoryId === 0) return true; // Todos
        if (activeCategoryId === -1) {
          // Favoritos
          return favorites.includes(channel.id);
        }
        return channel.categories.includes(activeCategoryId);
      });
    }

    // Apply Search on top of category result
    if (searchQuery) {
      result = result.filter(channel => 
        channel.name.toLowerCase().includes(searchQuery.toLowerCase())
      );
    }

    return result;
  }, [channels, activeCategoryId, searchQuery, favorites, history]);

  // Filter Logic for Games (Search only)
  const filteredGames = useMemo(() => {
    if (activeCategoryId !== -3) return [];
    if (!searchQuery) return games;

    const query = searchQuery.toLowerCase();

    return games.filter(g => {
        // Safe optional chaining to prevent crashes on bad data
        const titleMatch = g.title && g.title.toLowerCase().includes(query);
        const leagueMatch = g.data?.league && g.data.league.toLowerCase().includes(query);
        const homeMatch = g.data?.teams?.home?.name && g.data.teams.home.name.toLowerCase().includes(query);
        const awayMatch = g.data?.teams?.away?.name && g.data.teams.away.name.toLowerCase().includes(query);

        return titleMatch || leagueMatch || homeMatch || awayMatch;
    });
  }, [games, activeCategoryId, searchQuery]);

  // Filter Logic for Radios
  const filteredRadios = useMemo(() => {
    if (activeCategoryId !== -4) return [];
    if (!searchQuery) return radios;

    const query = searchQuery.toLowerCase();
    return radios.filter(r => 
        r.name.toLowerCase().includes(query) || 
        r.city.toLowerCase().includes(query) ||
        r.category.toLowerCase().includes(query)
    );
  }, [radios, activeCategoryId, searchQuery]);

  const handleChannelSelect = (channel: Channel) => {
    navigate(`/watch/${channel.id}`);
  };

  const handleCategorySelect = (id: number) => {
    setActiveCategoryId(id);
    setSearchQuery(""); // Clear search on category change
  };

  return (
    <div className="flex-1 flex flex-col">
      <Header 
        searchTerm={searchQuery} 
        onSearch={setSearchQuery}
      />

      <CategoryList 
        categories={categories} 
        activeCategoryId={activeCategoryId} 
        onSelectCategory={handleCategorySelect} 
      />

      <div className="flex-1">
        <div className="container mx-auto px-4 py-4">
           <div className="flex items-center gap-2 mb-2">
              <div className="w-1 h-6 bg-primary rounded-full"></div>
              <h2 className="text-xl font-bold text-white">
                {categories.find(c => c.id === activeCategoryId)?.name || 'Canais'}
                {searchQuery && <span className="text-gray-400 font-normal text-base ml-2">- Buscando por "{searchQuery}"</span>}
              </h2>
           </div>

           {activeCategoryId === -3 ? (
             <GameList games={filteredGames} loading={loadingGames} />
           ) : activeCategoryId === -4 ? (
             <RadioList radios={filteredRadios} />
           ) : (
             <ChannelGrid 
               channels={filteredChannels} 
               onSelectChannel={handleChannelSelect}
               favorites={favorites}
               onToggleFavorite={toggleFavorite}
             />
           )}
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { Category } from '../types';
import { 
  LayoutGrid, 
  Flame, 
  Trophy, 
  Baby, 
  Globe, 
  Clapperboard, 
  Newspaper, 
  Tv, 
  Shuffle,
  Heart,
  History,
  Gamepad2,
  Clock,
  Music,
  BookOpen,
  Radio,
  Calendar,
  LucideIcon 
} from 'lucide-react';

interface CategoryListProps {
  categories: Category[];
  activeCategoryId: number;
  onSelectCategory: (id: number) => void;
}

// Map category IDs to specific icons
const getCategoryIcon = (id: number): LucideIcon => {
  switch (id) {
    case 0: return LayoutGrid;    // Todos
    case -1: return Heart;        // Favoritos
    case -2: return History;      // Recentes
    case -3: return Trophy;       // Futebol Ao vivo
    case -4: return Radio;        // Rádios
    case 8: return Flame;         // BBB
    case 6: return Tv;            // TV Aberta
    case 1: return Trophy;        // Esportes
    case 4: return Clapperboard;  // Filmes e Séries
    case 9: return Clock;         // 24 Horas
    case 2: return Baby;          // Infantil
    case 5: return Newspaper;     // Noticias
    case 3: return Globe;         // Documentarios
    case 7: return Shuffle;       // Variedades
    case 10: return BookOpen;     // Religiosos
    case 11: return Music;        // Música
    default: return Tv;
  }
};

export const CategoryList: React.FC<CategoryListProps> = ({ 
  categories, 
  activeCategoryId, 
  onSelectCategory 
}) => {
  return (
    <div className="w-full bg-dark border-b border-gray-800 sticky top-[65px] z-40 shadow-sm">
      <div className="container mx-auto px-4 py-3">
        <div className="flex gap-3 overflow-x-auto no-scrollbar pb-1">
          {categories.map((category) => {
            const Icon = getCategoryIcon(category.id);
            const isActive = activeCategoryId === category.id;

            return (
              <button
                key={category.id}
                onClick={() => onSelectCategory(category.id)}
                className={`
                  whitespace-nowrap px-4 py-2 rounded-xl text-sm font-semibold transition-all duration-300
                  flex items-center gap-2 flex-shrink-0 border
                  ${isActive 
                    ? 'bg-primary text-white border-primary shadow-lg shadow-primary/25 scale-105' 
                    : 'bg-card text-gray-400 border-gray-700 hover:bg-gray-700 hover:text-white hover:border-gray-500'}
                `}
              >
                <Icon className={`w-4 h-4 ${isActive ? 'text-white' : 'text-gray-500 group-hover:text-white'} ${category.id === -1 && !isActive ? 'text-primary' : ''}`} />
                {category.name}
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { useRadio } from '../contexts/RadioContext';
import { useLocation, useNavigate } from 'react-router-dom';
import { Play, Pause, X, Radio as RadioIcon, Maximize2, Volume2, VolumeX, ChevronUp } from 'lucide-react';

export const GlobalRadioPlayer: React.FC = () => {
  const { 
    activeRadio, 
    isPlaying, 
    togglePlay, 
    stopRadio, 
    setBufferingState, 
    setPlayingState 
  } = useRadio();

  const audioRef = useRef<HTMLAudioElement>(null);
  const location = useLocation();
  const navigate = useNavigate();
  const [volume, setVolume] = useState(1);
  const [isMuted, setIsMuted] = useState(false);

  // O Mini Player só aparece se tiver rádio ativa E não estivermos na página de detalhe da rádio
  const isWatchPage = location.pathname.includes('/watch/') && activeRadio && location.pathname.includes(activeRadio.id);
  const showMiniPlayer = activeRadio && !isWatchPage;

  // Lógica de Controle de Áudio
  useEffect(() => {
    if (!audioRef.current || !activeRadio) return;

    const audio = audioRef.current;

    if (audio.src !== activeRadio.url) {
      audio.src = activeRadio.url;
      audio.load();
    }

    if (isPlaying) {
      audio.play().catch(error => {
        console.error("Erro ao reproduzir:", error);
        setPlayingState(false);
      });
    } else {
      audio.pause();
    }

    if ('mediaSession' in navigator) {
      navigator.mediaSession.metadata = new MediaMetadata({
        title: activeRadio.name,
        artist: activeRadio.currentProgram || 'Rádio Online',
        artwork: [{ src: activeRadio.image, sizes: '512x512', type: 'image/png' }]
      });

      navigator.mediaSession.setActionHandler('play', () => togglePlay());
      navigator.mediaSession.setActionHandler('pause', () => togglePlay());
      navigator.mediaSession.setActionHandler('stop', () => stopRadio());
    }

  }, [activeRadio, isPlaying, togglePlay, stopRadio, setPlayingState]);

  // Controle de Volume
  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = isMuted ? 0 : volume;
    }
  }, [volume, isMuted]);

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newVol = parseFloat(e.target.value);
    setVolume(newVol);
    if (newVol > 0) setIsMuted(false);
  };

  const toggleMute = () => setIsMuted(!isMuted);

  const expandPlayer = () => {
    if (activeRadio) {
      navigate(`/watch/${activeRadio.id}`);
    }
  };

  // CSS para as barras de áudio
  const AudioBars = () => (
    <div className="flex items-end gap-[2px] h-4">
      <div className={`w-1 bg-primary rounded-t-sm ${isPlaying ? 'animate-[bounce_1s_infinite]' : 'h-1'}`}></div>
      <div className={`w-1 bg-primary rounded-t-sm ${isPlaying ? 'animate-[bounce_1.2s_infinite]' : 'h-2'}`}></div>
      <div className={`w-1 bg-primary rounded-t-sm ${isPlaying ? 'animate-[bounce_0.8s_infinite]' : 'h-3'}`}></div>
      <div className={`w-1 bg-primary rounded-t-sm ${isPlaying ? 'animate-[bounce_1.1s_infinite]' : 'h-1'}`}></div>
    </div>
  );

  return (
    <>
      <audio
        ref={audioRef}
        onCanPlay={() => setBufferingState(false)}
        onWaiting={() => setBufferingState(true)}
        onPlaying={() => { setPlayingState(true); setBufferingState(false); }}
        onPause={() => setPlayingState(false)}
        onError={() => { setPlayingState(false); setBufferingState(false); }}
        style={{ display: 'none' }}
      />

      {showMiniPlayer && (
        <div className="fixed bottom-0 left-0 right-0 z-50 animate-in slide-in-from-bottom duration-500">
            {/* Barra de Progresso Infinita (Estética) */}
            {isPlaying && (
                <div className="w-full h-0.5 bg-gray-800 overflow-hidden">
                    <div className="h-full bg-gradient-to-r from-transparent via-primary to-transparent w-full animate-[shimmer_2s_infinite_-1s]"></div>
                </div>
            )}

            <div className="bg-gray-900/90 backdrop-blur-xl border-t border-white/10 p-3 shadow-[0_-10px_40px_rgba(0,0,0,0.5)]">
            <div className="container mx-auto max-w-6xl flex items-center justify-between gap-4">

              {/* Info Area */}
              <div 
                className="flex items-center gap-4 flex-1 min-w-0 cursor-pointer group"
                onClick={expandPlayer}
              >
                <div className="relative">
                  <div className={`absolute inset-0 bg-primary/20 blur-lg rounded-full ${isPlaying ? 'animate-pulse' : 'hidden'}`}></div>
                  <img 
                    src={activeRadio.image} 
                    alt={activeRadio.name} 
                    className={`relative w-12 h-12 object-cover rounded-xl border border-white/10 shadow-lg ${isPlaying ? '' : 'grayscale'}`}
                    onError={(e) => (e.currentTarget.src = 'https://cdn-icons-png.flaticon.com/512/3135/3135715.png')}
                  />
                  <div className="absolute -top-1 -right-1 bg-black rounded-full p-0.5 border border-white/10">
                    <RadioIcon className="w-3 h-3 text-primary" />
                  </div>
                </div>

                <div className="flex flex-col overflow-hidden">
                  <div className="flex items-center gap-2">
                    <h4 className="text-white font-bold text-sm truncate group-hover:text-primary transition-colors">
                      {activeRadio.name}
                    </h4>
                    {isPlaying && <div className="hidden sm:block"><AudioBars /></div>}
                  </div>
                  <span className="text-xs text-gray-400 truncate font-medium">
                    {activeRadio.currentProgram || 'Ao Vivo'}
                  </span>
                </div>
              </div>

              {/* Controls */}
              <div className="flex items-center gap-3 md:gap-6">

                {/* Volume Control (Desktop) */}
                <div className="hidden md:flex items-center gap-2 group/vol">
                  <button onClick={(e) => { e.stopPropagation(); toggleMute(); }} className="text-gray-400 hover:text-white">
                    {isMuted || volume === 0 ? <VolumeX className="w-5 h-5" /> : <Volume2 className="w-5 h-5" />}
                  </button>
                  <div className="w-0 overflow-hidden group-hover/vol:w-20 transition-all duration-300">
                    <input
                      type="range"
                      min="0"
                      max="1"
                      step="0.05"
                      value={isMuted ? 0 : volume}
                      onChange={handleVolumeChange}
                      onClick={(e) => e.stopPropagation()}
                      className="w-20 h-1 bg-gray-600 rounded-lg appearance-none cursor-pointer accent-primary"
                    />
                  </div>
                </div>

                <div className="flex items-center gap-3">
                    <button 
                      onClick={(e) => { e.stopPropagation(); togglePlay(); }}
                      className="w-12 h-12 bg-white text-black rounded-full flex items-center justify-center hover:scale-105 active:scale-95 transition-all shadow-lg hover:shadow-white/20"
                    >
                      {isPlaying ? (
                        <Pause className="w-5 h-5 fill-current" />
                      ) : (
                        <Play className="w-5 h-5 fill-current ml-1" />
                      )}
                    </button>

                    <button 
                       onClick={(e) => { e.stopPropagation(); expandPlayer(); }}
                       className="p-2.5 bg-white/5 hover:bg-white/10 rounded-full text-gray-300 hover:text-white transition-colors border border-white/5 hidden sm:block"
                       title="Expandir"
                    >
                        <ChevronUp className="w-5 h-5" />
                    </button>

                    <button 
                      onClick={(e) => { e.stopPropagation(); stopRadio(); }}
                      className="p-2 text-gray-500 hover:text-red-500 transition-colors"
                      title="Fechar"
                    >
                      <X className="w-6 h-6" />
                    </button>
                </div>
              </div>

            </div>
          </div>
        </div>
      )}
    </>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Channel } from '../types';
import { 
  Maximize2, 
  AlertCircle, 
  Loader2, 
  ArrowLeft, 
  Volume2, 
  VolumeX, 
  Expand,
  Minimize2,
  Sparkles,
  ExternalLink,
  Cast,
  Radio,
  Music2,
  Play,
  Pause,
  Calendar,
  Signal
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { generateChannelDescription, Source } from '../services/aiService';
import { castMedia, requestSession, getCastContext, CAST_STATES, initializeCastApi } from '../services/castService';
import { InstallAppModal } from './InstallAppModal';
import { useRadio } from '../contexts/RadioContext';
import { useEPG } from '../contexts/EPGContext';

interface PlayerProps {
  channel: Channel;
}

export const Player: React.FC<PlayerProps> = ({ channel }) => {
  const navigate = useNavigate();

  // Contexts
  const { 
    activeRadio, 
    isPlaying: isRadioPlaying, 
    isBuffering: isRadioBuffering,
    playRadio, 
    togglePlay: toggleRadioPlay 
  } = useRadio();

  const { getChannelEPG } = useEPG();

  const isRadio = channel.categories.includes(-4);

  const [isLoading, setIsLoading] = useState(true);
  const [hasError, setHasError] = useState(false);
  const [iframeKey, setIframeKey] = useState(0);

  // AI/EPG States
  const [aiDescription, setAiDescription] = useState<string | null>(null);
  const [epgData, setEpgData] = useState<ReturnType<typeof getChannelEPG>>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // UI States
  const [isCinemaMode, setIsCinemaMode] = useState(false);
  const [showControls, setShowControls] = useState(true);
  const [volume, setVolume] = useState(100);
  const [isMuted, setIsMuted] = useState(false);

  // Local state for Video (Radio uses context)
  const [isVideoPlaying, setIsVideoPlaying] = useState(false);

  const controlsTimeoutRef = useRef<number | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Cast State
  const [castState, setCastState] = useState<string>('NO_DEVICES_AVAILABLE');
  const [showInstallModal, setShowInstallModal] = useState(false);

  useEffect(() => {
    // Reset state when channel changes
    setHasError(false);
    setIframeKey(prev => prev + 1);

    if (!isRadio) {
        setIsLoading(true);
        setIsVideoPlaying(false);
    } else {
        setIsLoading(false);
        if (activeRadio?.id !== channel.id) {
            playRadio(channel);
        }
    }

    // EPG Data Update Loop
    const updateEPG = () => {
        const data = getChannelEPG(channel.name);
        setEpgData(data);
    };

    updateEPG(); // Initial fetch
    const epgInterval = setInterval(updateEPG, 60000); // Update every minute for progress bar

    // AI Description (Legacy fallback)
    setAiDescription(null);
    if (!epgData) { // Only fetch AI if no EPG
        const fetchDescription = async () => {
          setLoadingAi(true);
          const result = await generateChannelDescription(channel.name);
          if (result) {
            setAiDescription(result.text);
          }
          setLoadingAi(false);
        };
        fetchDescription();
    }

    initializeCastApi();
    const setupCast = () => {
        const context = getCastContext();
        if (context) {
            setCastState(context.getCastState());
            const handler = (e: any) => setCastState(e.castState);
            context.addEventListener(window.cast.framework.CastContextEventType.CAST_STATE_CHANGED, handler);
            return () => context.removeEventListener(window.cast.framework.CastContextEventType.CAST_STATE_CHANGED, handler);
        }
    };

    const cleanupCast = setupCast();

    return () => {
        clearInterval(epgInterval);
        if (cleanupCast) cleanupCast();
    };

  }, [channel.id, channel.name, isRadio, getChannelEPG]);

  const isPlaying = isRadio ? isRadioPlaying : isVideoPlaying;
  const isBuffering = isRadio ? isRadioBuffering : isLoading;

  const handleVideoLoad = () => {
    setIsLoading(false);
    setIsVideoPlaying(true);
  };

  const handleTogglePlay = (e?: React.MouseEvent) => {
      e?.stopPropagation();
      if (isRadio) {
          toggleRadioPlay();
      }
  };

  const handleFullscreen = () => {
    const playerElement = document.getElementById('video-player-container');
    if (playerElement) {
      if (document.fullscreenElement) {
        document.exitFullscreen();
      } else {
        playerElement.requestFullscreen();
      }
    }
  };

  const toggleCinemaMode = () => {
    setIsCinemaMode(!isCinemaMode);
    setShowControls(true);
    if (controlsTimeoutRef.current) {
      window.clearTimeout(controlsTimeoutRef.current);
    }
    controlsTimeoutRef.current = window.setTimeout(() => {
      if (!isLoading) setShowControls(false);
    }, 3000);
  };

  const handleReload = () => {
    if (isRadio) {
        playRadio(channel);
    } else {
        setIsLoading(true);
        setHasError(false);
        setIframeKey(prev => prev + 1);
    }
  };

  const handleBack = () => {
    navigate(-1);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newVol = parseInt(e.target.value);
    setVolume(newVol);
    if (newVol > 0 && isMuted) setIsMuted(false);
    if (newVol === 0) setIsMuted(true);
  };

  const toggleMute = () => {
    setIsMuted(!isMuted);
    if (isMuted && volume === 0) setVolume(50);
  };

  const handleInteraction = useCallback(() => {
    setShowControls(true);
    if (controlsTimeoutRef.current) {
      window.clearTimeout(controlsTimeoutRef.current);
    }
    controlsTimeoutRef.current = window.setTimeout(() => {
      if (!isBuffering && (isPlaying || !isRadio)) { 
          setShowControls(false);
      }
    }, 3000);
  }, [isBuffering, isPlaying, isRadio]);

  const handleCastClick = () => {
    setShowInstallModal(true);
  };

  const handleInstallApp = () => {
      window.open("https://play.google.com/store/apps/details?id=cast.video.screenmirroring.casttotv&hl=pt_BR", "_blank");
      setShowInstallModal(false);
  };

  const handleNativeCast = async () => {
    setShowInstallModal(false);
    if (castState === CAST_STATES.NO_DEVICES_AVAILABLE) {
        alert("Nenhum dispositivo Chromecast encontrado.");
        return;
    }
    if (castState === CAST_STATES.CONNECTED) {
        castMedia(channel.url, channel.name, channel.image);
    } else {
        const connected = await requestSession();
        if (connected) {
            setTimeout(() => {
                castMedia(channel.url, channel.name, channel.image);
            }, 500);
        }
    }
  };

  const isCastConnected = castState === CAST_STATES.CONNECTED;

  // Componente de Barras de Visualizer para Rádio
  const RadioVisualizerBars = () => (
    <div className="flex items-end justify-center gap-1.5 h-12">
        {[...Array(8)].map((_, i) => (
            <div 
                key={i} 
                className={`w-2 bg-primary/80 rounded-t-md ${isPlaying ? 'animate-[bounce_0.8s_infinite]' : 'h-2'}`}
                style={{ 
                    animationDuration: `${0.6 + (i * 0.1)}s`,
                    height: isPlaying ? '100%' : '10%'
                }}
            ></div>
        ))}
    </div>
  );

  return (
    <div className={`transition-all duration-500 ${
      isCinemaMode 
        ? 'fixed inset-0 z-50 bg-black flex flex-col justify-center' 
        : 'w-full bg-dark pt-4 pb-6 relative'
    }`}>
      <InstallAppModal 
        isOpen={showInstallModal}
        onClose={handleNativeCast}
        onDismiss={() => setShowInstallModal(false)}
        onConfirm={handleInstallApp}
      />
      <div 
        className={`mx-auto transition-all duration-500 ${
          isCinemaMode 
            ? 'w-full h-full' 
            : 'container px-4 max-w-6xl'
        }`}
      >
        {/* Header Section - Hidden in Cinema Mode */}
        {!isCinemaMode && (
          <div className="flex items-center gap-4 mb-4 text-white">
               <button 
                  onClick={handleBack}
                  className="p-2 hover:bg-white/10 rounded-full transition-colors flex items-center justify-center"
                  aria-label="Voltar"
               >
                  <ArrowLeft className="w-6 h-6" />
               </button>
               <div className="flex-1">
                  <h2 className="text-xl sm:text-2xl font-bold leading-tight line-clamp-1">{channel.name}</h2>
                  <div className="flex items-center gap-2">
                    {isRadio && isPlaying && (
                       <div className="flex items-end gap-0.5 h-3">
                         <span className="w-0.5 h-2 bg-red-500 animate-[pulse_1s_infinite]"></span>
                         <span className="w-0.5 h-3 bg-red-500 animate-[pulse_1.2s_infinite]"></span>
                         <span className="w-0.5 h-2 bg-red-500 animate-[pulse_0.8s_infinite]"></span>
                       </div>
                    )}
                    <p className="text-sm text-gray-300 font-medium truncate">
                      {epgData ? (
                        <span className="text-primary font-bold uppercase">{epgData.title}</span>
                      ) : (
                        channel.currentProgram || (isRadio ? "Rádio Ao Vivo" : "Transmissão Ao Vivo")
                      )}
                    </p>
                  </div>
               </div>
          </div>
        )}

        {/* Player Container */}
        <div 
          id="video-player-container" 
          ref={containerRef}
          className={`
            relative bg-black overflow-hidden group
            ${isCinemaMode 
              ? `w-full h-full ${!showControls ? 'cursor-none' : 'cursor-default'}` 
              : 'rounded-xl aspect-video w-full shadow-2xl ring-1 ring-white/10'
            }
          `}
          onMouseMove={handleInteraction}
          onClick={handleInteraction}
          onTouchStart={handleInteraction}
        >
          {isBuffering && (
            <div className="absolute inset-0 flex flex-col items-center justify-center bg-gray-900/90 z-10 text-white backdrop-blur-sm">
              <Loader2 className="w-12 h-12 animate-spin text-primary mb-3" />
              <p className="text-base font-medium text-gray-300 animate-pulse">
                  {isRadio ? 'Sintonizando frequência...' : 'Carregando sinal...'}
              </p>
            </div>
          )}

          {hasError ? (
             <div className="absolute inset-0 flex flex-col items-center justify-center bg-gray-900 z-20 text-white p-4 text-center">
               <AlertCircle className="w-16 h-16 text-red-500 mb-4" />
               <p className="text-xl font-bold mb-2">Sinal Indisponível</p>
               <p className="text-gray-400 text-base mb-6 max-w-md">
                 Não foi possível conectar ao servidor.
               </p>
               <button 
                 onClick={handleReload}
                 className="px-8 py-3 bg-primary hover:bg-red-600 rounded-full font-bold transition-colors shadow-lg shadow-primary/20"
               >
