import { EPGChannel, EPGProgram } from '../types';

// URL XMLTV Original (HTTP)
const EPG_URL = 'http://nocable.cc:8080/xmltv.php?username=J0WfUK&password=016294';

// Lista de proxies para contornar bloqueios de CORS e Mixed Content
const PROXIES = [
  // 1. CorsProxy.io: Rápido e confiável
  (url: string) => `https://corsproxy.io/?${encodeURIComponent(url)}`,
  // 2. CodeTabs: Ótima alternativa para APIs públicas
  (url: string) => `https://api.codetabs.com/v1/proxy?quest=${encodeURIComponent(url)}`,
  // 3. AllOrigins: Fallback robusto (com timestamp para evitar cache antigo)
  (url: string) => `https://api.allorigins.win/raw?url=${encodeURIComponent(url)}&t=${Date.now()}`
];

/**
 * Parse seguro de data XMLTV
 * Formato padrão: YYYYMMDDHHMMSS +0000 ou YYYYMMDDHHMMSS -0300
 */
const parseXMLTVDate = (dateStr: string): Date => {
  if (!dateStr || dateStr.length < 14) return new Date(0);

  const year = dateStr.slice(0, 4);
  const month = dateStr.slice(4, 6);
  const day = dateStr.slice(6, 8);
  const hour = dateStr.slice(8, 10);
  const min = dateStr.slice(10, 12);
  const sec = dateStr.slice(12, 14);

  // Extrai o timezone se existir (ex: -0300 ou +0000)
  // Se não existir, assume UTC (Z)
  // O XMLTV geralmente retorna UTC ou local. Para simplificar e evitar erros
  // de parsing cross-browser, forçamos o ISO UTC.
  return new Date(`${year}-${month}-${day}T${hour}:${min}:${sec}Z`);
};

export const fetchEPG = async (): Promise<EPGChannel[]> => {
  // Tenta cada proxy na lista até conseguir sucesso
  for (const createProxyUrl of PROXIES) {
    try {
      const proxyUrl = createProxyUrl(EPG_URL);
      console.log(`[EPG] Tentando carregar via: ${proxyUrl}`);

      // Timeout de 15 segundos para não travar a aplicação em proxy lento
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 15000);

      const response = await fetch(proxyUrl, { signal: controller.signal });
      clearTimeout(timeoutId);

      if (!response.ok) {
        console.warn(`[EPG] Falha no proxy (${response.status}): ${proxyUrl}`);
        continue; // Tenta o próximo proxy
      }

      const xmlText = await response.text();

      // Validação básica do conteúdo
      if (!xmlText || (!xmlText.trim().startsWith('<') && !xmlText.includes('<tv'))) {
        console.warn('[EPG] Conteúdo retornado não parece ser um XML válido.');
        continue;
      }

      const parser = new DOMParser();
      const xmlDoc = parser.parseFromString(xmlText, 'text/xml');

      if (xmlDoc.querySelector('parsererror')) {
        console.error('[EPG] Erro ao fazer parse do XML.');
        continue;
      }

      const channelMap = new Map<string, EPGChannel>();

      // ===== 1. Processar Canais =====
      xmlDoc.querySelectorAll('channel').forEach((el) => {
        const id = el.getAttribute('id');
        const displayName =
          el.querySelector('display-name')?.textContent?.trim() || '';

        if (id) {
          channelMap.set(id, {
            id,
            displayName,
            programs: []
          });
        }
      });

      // Definição de janela de tempo para otimização de memória
      const now = new Date();
      const twoHoursAgo = new Date(now.getTime() - 2 * 60 * 60 * 1000);
      const next24h = new Date(now.getTime() + 24 * 60 * 60 * 1000);

      // ===== 2. Processar Programas =====
      const programs = xmlDoc.querySelectorAll('programme');

      programs.forEach((el) => {
        const channelId = el.getAttribute('channel');
        // Pula se o canal não foi mapeado
        if (!channelId || !channelMap.has(channelId)) return;

        const start = parseXMLTVDate(el.getAttribute('start') || '');
        const end = parseXMLTVDate(el.getAttribute('stop') || '');

        // Filtro: Ignora programas muito antigos ou muito no futuro
        if (end < twoHoursAgo || start > next24h) return;

        const title =
          el.querySelector('title')?.textContent?.trim() || 'Sem título';
        const desc =
          el.querySelector('desc')?.textContent?.trim() || '';

        channelMap.get(channelId)!.programs.push({
          title,
          description: desc,
          start,
          end,
          channelId
        });
      });

      const result = Array.from(channelMap.values()).filter(
        (c) => c.programs.length > 0
      );

      console.log(`[EPG] Sucesso! ${result.length} canais carregados com programação.`);
      return result; // Retorna assim que conseguir sucesso

    } catch (error) {
      console.warn('[EPG] Erro de rede/timeout ao tentar proxy:', error);
      // Continua para o próximo proxy no loop
    }
  }

  console.error('[EPG] Todas as tentativas de conexão falharam.');
  return [];
};

// ===== HELPERS EXPORTADOS =====

export const getCurrentProgram = (
  epgChannel: EPGChannel
): EPGProgram | null => {
  const now = new Date();
  return epgChannel.programs.find(
    (p) => now >= p.start && now < p.end
  ) || null;
};

export const normalizeStr = (str: string): string => {
  return str
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]/g, '')
    .replace('fhd', '')
    .replace('hd', '')
    .replace('4k', '')
    .replace('br', '')
    .replace('bra', '') // Filtro extra comum
    .replace('pl', '') // Filtro extra comum
    .trim();
};
